//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/gating/icg_cell.sv
// Module    : icg_cell
// Content   : latch-based integrated clock gate (behavioural model of a
//             library clock-gating cell, CGC). The enable is captured while
//             the clock is low, so gclk never glitches.
// Used in   : pmu_top (one per clock domain in MODE 1/2, one per clock net
//             in MODE 3/4)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module icg_cell (
  input  wire  clk,
  input  wire  en,
  output logic gclk
);
  logic en_lat;

  // transparent while clk is low (intended latch)
  always_latch begin
    if (!clk) en_lat = en;
  end

  assign gclk = clk & en_lat;
endmodule : icg_cell

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/gating/pg_dff.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/gating/pg_dff.sv
// Module    : pg_dff
// Content   : D flip-flop inside a (possibly) power-gated domain
//   RET = 0 : normal flop    - X while powered off, reset value on power-up init
//   RET = 1 : retention flop - keeps its value while off if pd_ret was raised
//             before the switch opened
// Power gating is modelled in RTL (no UPF needed to simulate): a wrong
// safety-shell sequence shows up as X / wrong data in the lock-step scoreboard.
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module pg_dff #(
  parameter int unsigned  W   = 1,
  parameter logic [W-1:0] RV  = '0,     // reset / power-up value
  parameter int           RET = 0       // 1 = retention flop
) (
  input  wire          clk,
  input  wire          rst_n,
  input  wire          pd_on,    // domain powered (switch closed and settled)
  input  wire          pd_ret,   // retention save request
  input  wire          pd_init,  // power-up initialisation of non-retention state
  input  wire          en,
  input  wire  [W-1:0] d,
  output logic [W-1:0] q
);
  always_ff @(posedge clk or negedge rst_n or negedge pd_on or posedge pd_init) begin
    if (!rst_n) begin
      q <= RV;
    end else if (!pd_on) begin
      if (!((RET != 0) && pd_ret)) q <= 'x;
    end else if (pd_init) begin
      if (RET == 0) q <= RV;
    end else if (en) begin
      q <= d;
    end
  end
endmodule : pg_dff

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/gating/pwr_switch_model.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/gating/pwr_switch_model.sv
// Module    : pwr_switch_model
// Content   : header power switch + supply settle time.
//             The switch opens one cycle after pwr_req falls (supply decays)
//             and reports "settled" (ack = pd_on = 1) WAKE cycles after
//             pwr_req rises. Both edges come from flops.
// Used in   : pm_domain (power-gating domains only)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module pwr_switch_model #(
  parameter int WAKE = 4
) (
  input  wire  clk,
  input  wire  rst_n,
  input  wire  pwr_req,
  output logic ack,
  output logic pd_on
);
  localparam logic [7:0] WK = 8'(WAKE);

  logic [7:0] cnt;
  logic       ack_r;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      cnt   <= WK;
      ack_r <= 1'b1;
    end else if (!pwr_req) begin
      cnt   <= 8'd0;
      ack_r <= 1'b0;
    end else begin
      if (cnt != WK) cnt <= cnt + 8'd1;
      ack_r <= ((cnt + 8'd1) >= WK);
    end
  end

  assign ack   = ack_r;
  assign pd_on = ack_r;
endmodule : pwr_switch_model

`default_nettype wire

