// Content   : isolation cells on a power-domain boundary (behavioural model of
//             library isolation cells, UPF set_isolation). While iso = 1 the
//             outputs of the domain are clamped to CLAMP.
// Used in   : every power leaf on its outputs (EX, CORE, RF-HI, banks ...)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module iso_clamp #(
  parameter int unsigned  W     = 1,
  parameter logic [W-1:0] CLAMP = '0
) (
  input  wire          iso,
  input  wire  [W-1:0] d,
  output logic [W-1:0] q
);
  assign q = iso ? CLAMP : d;
endmodule : iso_clamp

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/pmu/policy_reactive.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/pmu/policy_reactive.sv
// Module    : policy_reactive
// Content   : idle-counter threshold policy (existing-work baseline,
//             #080 stall-driven CG / #079 idle-threshold PG).
//             req_class : 0 none, 1 CG, 2 PG_RET, 3 PG_OFF
// Hierarchy : pmu_top > pm_domain > u_policy
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module policy_reactive
  import fido_pkg::*;
#(
  parameter int MODE = MODE_CG,   // MODE_CG: request CG, MODE_PG: request PG
  parameter int THR  = 8          // idle cycles before the request
) (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        busy,
  input  wire        live,
  output logic [1:0] req_class
);
  localparam logic [7:0] T8 = 8'(THR);

  logic [7:0] idle;
  logic       hit;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)             idle <= 8'd0;
    else if (busy)          idle <= 8'd0;
    else if (idle != 8'hFF) idle <= idle + 8'd1;
  end

  assign hit       = (idle >= T8);
  assign req_class = (!hit)           ? RQ_NONE   :
                     (MODE == MODE_CG) ? RQ_CG     :
                     (live)            ? RQ_PG_RET : RQ_PG_OFF;
endmodule : policy_reactive

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/pmu/policy_ml_wrap.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/pmu/policy_ml_wrap.sv
// Module    : policy_ml_wrap
// Content   : selects the power-gating request of one power domain in MODE 4
//             from the exported ML model, with the ml_force test hook:
//               ml_force 0 : model decides {conf, class}
//               ml_force 1 : force a confident PG_OFF request
//               ml_force 2 : force confidence 0 (shell refuses every PG request)
//               ml_force 3 : reactive policy (training-trace mode)
//             The model can only request; the safety shell decides.
// Hierarchy : pmu_top > pm_domain > g_ml.u_ml
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module policy_ml_wrap
  import fido_pkg::*;
(
  input  wire  [1:0] ml_force,
  input  wire  [1:0] r_class,     // reactive policy request
  input  wire  [2:0] model_dec,   // {confidence, class} from ml_models_*
  output logic [1:0] req_class,
  output logic       conf
);
  assign req_class = (ml_force == 2'd3) ? r_class   :
                     (ml_force == 2'd1) ? RQ_PG_OFF : model_dec[1:0];
  assign conf      = (ml_force == 2'd3) || (ml_force == 2'd1) ||
                     ((ml_force == 2'd0) && model_dec[2]);
endmodule : policy_ml_wrap

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/pmu/safety_shell.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/pmu/safety_shell.sv
// Module    : safety_shell
// Content   : per-domain FSM. The policy can only request; the shell enforces
//             order and timing. A power-gating request is taken only when the
//             policy's confidence bit is 1.
//               ON -> CG                       (MODE = CG)
//               ON -> ISO -> [SAVE] -> OFF     (MODE = PG; SAVE only when live)
//               OFF -> PWRUP -> INIT -> REST -> ISOREL -> ON
//             pm_state : 0 ON, 1 CG, 2 PG_RET, 3 PG_OFF, 4 WAKING
//             Power-control outputs are registered (glitch-free into the
//             asynchronous power-down / init / retention controls).
// Hierarchy : pmu_top > pm_domain > u_shell
// SVA (later bind file shell_sva.sv): SH-1 .. SH-7
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module safety_shell
  import fido_pkg::*;
#(
  parameter int MODE = MODE_CG,   // MODE_CG or MODE_PG
  parameter int BE   = 8,         // break-even: wake earlier = mispredict
  parameter int HYST = 8          // lock-ON cycles after a mispredict
) (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        busy,
  input  wire        live,
  input  wire        trap_win,
  input  wire  [1:0] req_class,
  input  wire        conf,
  input  wire        ack_pwr,
  output logic       clk_en,
  output logic       iso,
  output logic       ret,
  output logic       pwr_req,
  output logic       init,
  output logic       ready,
  output logic [2:0] pm_state,
  output logic       mispredict
);
  typedef enum logic [3:0] {
    S_ON     = 4'd0,
    S_CG     = 4'd1,
    S_ISO    = 4'd2,
    S_SAVE   = 4'd3,
    S_OFF    = 4'd4,
    S_PWRUP  = 4'd5,
    S_INIT   = 4'd6,
    S_REST   = 4'd7,
    S_ISOREL = 4'd8
  } state_e;

  localparam logic [7:0] BE8 = 8'(BE);
  localparam logic [7:0] HY8 = 8'(HYST);

  state_e     st;
  state_e     st_n;
  logic       tgt_ret;
  logic       tgt_n;
  logic [7:0] age;
  logic [7:0] lock;
  logic       iso_r;
  logic       ret_r;
  logic       pwr_r;
  logic       init_r;

  logic can_gate;
  logic acc_cg;
  logic acc_pg;
  logic gated;

  assign can_gate = !busy && !trap_win && (lock == 8'd0);
  assign acc_cg   = (MODE == MODE_CG) && can_gate && (req_class == RQ_CG);
  // power-gating requests are accepted only with confidence = 1
  // (reactive policy: always 1; ML policy: model confidence bit)
  assign acc_pg   = (MODE == MODE_PG) && can_gate && conf &&
                    ((req_class == RQ_PG_RET) || (req_class == RQ_PG_OFF));
  assign gated    = (st == S_CG) || (st == S_OFF);

  assign mispredict = gated && busy && (age < BE8);

  //---------------------------------------------------------- next state
  always_comb begin
    st_n  = st;
    tgt_n = tgt_ret;
    case (st)
      S_ON: begin
        if (acc_cg) begin
          st_n = S_CG;
        end else if (acc_pg) begin
          st_n  = S_ISO;
          tgt_n = live || (req_class == RQ_PG_RET);
        end
      end
      S_CG: begin
        if (busy) st_n = S_ON;
      end
      S_ISO: begin
        tgt_n = tgt_ret || live;
        if (busy)                 st_n = S_ISOREL;
        else if (tgt_ret || live) st_n = S_SAVE;
        else                      st_n = S_OFF;
      end
      S_SAVE: begin
        if (busy) st_n = S_REST;
        else      st_n = S_OFF;
      end
      S_OFF: begin
        if (busy) st_n = S_PWRUP;
      end
      S_PWRUP: begin
        if (ack_pwr) st_n = S_INIT;
      end
      S_INIT:   st_n = S_REST;
      S_REST:   st_n = S_ISOREL;
      S_ISOREL: st_n = S_ON;
      default:  st_n = S_ON;
    endcase
  end

  //---------------------------------------------------------- registers
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      st      <= S_ON;
      tgt_ret <= 1'b0;
      age     <= 8'd0;
      lock    <= 8'd0;
      iso_r   <= 1'b0;
      ret_r   <= 1'b0;
      pwr_r   <= 1'b1;
      init_r  <= 1'b0;
    end else begin
      if (mispredict)        lock <= HY8;
      else if (lock != 8'd0) lock <= lock - 8'd1;

      if (gated && !busy) begin
        if (age != 8'hFF) age <= age + 8'd1;
      end else begin
        age <= 8'd0;
      end

      st      <= st_n;
      tgt_ret <= tgt_n;
      iso_r   <= (st_n == S_ISO) || (st_n == S_SAVE) || (st_n == S_OFF) ||
                 (st_n == S_PWRUP) || (st_n == S_INIT) || (st_n == S_REST);
      ret_r   <= (st_n == S_SAVE) ||
                 (tgt_n && ((st_n == S_OFF) || (st_n == S_PWRUP) || (st_n == S_INIT)));
      pwr_r   <= (st_n != S_OFF);
      init_r  <= (st_n == S_INIT);
    end
  end

  //---------------------------------------------------------- outputs
  assign clk_en   = (st == S_ON) || ((st == S_CG) && busy);
  assign iso      = iso_r;
  assign ret      = ret_r;
  assign pwr_req  = pwr_r;
  assign init     = init_r;
  assign ready    = (st == S_ON) || (st == S_CG);
  assign pm_state = (st == S_ON) ? PM_ON :
                    (st == S_CG) ? PM_CG :
                    ((st == S_ISO) || (st == S_SAVE) || (st == S_OFF)) ?
                      (tgt_ret ? PM_PG_RET : PM_PG_OFF) :
                    PM_WAKING;
endmodule : safety_shell

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/pmu/pm_domain.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/pmu/pm_domain.sv
// Module    : pm_domain
// Content   : power-management controller of ONE domain:
//               u_policy  policy_reactive  (idle threshold)
//               g_ml      policy_ml_wrap   (POLICY_ML = 1: ML request + ml_force)
//               u_shell   safety_shell     (order / timing / confidence gate)
//               g_sw      pwr_switch_model (power-gating domains only)
//             SH_MODE = MODE_CG : clock-gating domain (no switch, ack = 1)
//             SH_MODE = MODE_PG : power-gating domain (header switch)
// Hierarchy : fido_top > u_pmu (pmu_top) > g_*.g_*[d].u_dom (pm_domain)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module pm_domain
  import fido_pkg::*;
#(
  parameter int SH_MODE   = MODE_CG,
  parameter int THR       = 8,
  parameter int BE        = 8,
  parameter int HYST      = 8,
  parameter int WAKE_PG   = 4,
  parameter int POLICY_ML = 0       // 1 = ML model decides power gating (MODE 4)
) (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        busy,
  input  wire        live,
  input  wire        trap_win,
  input  wire  [1:0] ml_force,
  input  wire  [2:0] model_dec,     // {confidence, class}; unused unless POLICY_ML
  output logic       clk_en,
  output logic       iso,
  output logic       ret,
  output logic       pwr_req,
  output logic       init,
  output logic       ready,
  output logic       ack,
  output logic       pd_on,
  output logic [2:0] pm_state,
  output logic       mispredict
);
  wire [1:0] r_class;
  wire [1:0] req;
  wire       conf;

  policy_reactive #(.MODE(SH_MODE), .THR(THR)) u_policy (
    .clk       (clk),
    .rst_n     (rst_n),
    .busy      (busy),
    .live      (live),
    .req_class (r_class)
  );

  if (POLICY_ML != 0) begin : g_ml
    policy_ml_wrap u_ml (
      .ml_force  (ml_force),
      .r_class   (r_class),
      .model_dec (model_dec),
      .req_class (req),
      .conf      (conf)
    );
  end else begin : g_re
    assign req  = r_class;
    assign conf = 1'b1;
  end

  safety_shell #(.MODE(SH_MODE), .BE(BE), .HYST(HYST)) u_shell (
    .clk        (clk),
    .rst_n      (rst_n),
    .busy       (busy),
    .live       (live),
    .trap_win   (trap_win),
    .req_class  (req),
    .conf       (conf),
    .ack_pwr    (ack),
    .clk_en     (clk_en),
    .iso        (iso),
    .ret        (ret),
    .pwr_req    (pwr_req),
    .init       (init),
    .ready      (ready),
    .pm_state   (pm_state),
    .mispredict (mispredict)
  );

  if (SH_MODE == MODE_PG) begin : g_sw
    pwr_switch_model #(.WAKE(WAKE_PG)) u_switch (
      .clk     (clk),
      .rst_n   (rst_n),
      .pwr_req (pwr_req),
      .ack     (ack),
      .pd_on   (pd_on)
    );
  end else begin : g_nosw
    assign ack   = 1'b1;
    assign pd_on = 1'b1;
  end
endmodule : pm_domain

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/pmu/ml_feature_block.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/pmu/ml_feature_block.sv
// Module    : ml_feature_block
// Content   : per power domain feature vector for the ML policy (MODE 4).
//             All features are registered (one cycle old), so the model is a
//             pure combinational function of flops. Always on (part of PMU).
//   feat[5:0]   idle   cycles since the domain was last busy (saturates at 63)
//   feat[8:6]   h1     length bin of the last finished idle period
//   feat[11:9]  h2     length bin of the idle period before that
//   feat[14:12] occ    pipeline occupancy (valid IF/ID, ID/EX, EX/MEM, MEM/WB)
//   feat[15]    wfi    core asleep in WFI
//   feat[19:16] evq    event-queue occupancy
//   feat[20]    live   domain holds state that must survive power-off
//   feat[21]    busy   present demand (NOT a model input - trace / oracle only)
//   bins: 0 <2, 1 <4, 2 <8, 3 <16, 4 <32, 5 <64, 6 <128, 7 >=128 cycles
// Hierarchy : fido_top > u_pmu > g_dual.g_pd[d].g_ml.u_feat
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module ml_feature_block (
  input  wire         clk,
  input  wire         rst_n,
  input  wire         busy,
  input  wire         live,
  input  wire         wfi,
  input  wire  [2:0]  occ,
  input  wire  [3:0]  evq,
  output logic [21:0] feat
);
  logic [7:0] run;
  logic       busy_q;
  logic [2:0] h1;
  logic [2:0] h2;
  logic [2:0] occ_q;
  logic       wfi_q;
  logic [3:0] evq_q;
  logic [2:0] run_bin;
  logic [5:0] idle;

  assign run_bin = (run < 8'd2)   ? 3'd0 :
                   (run < 8'd4)   ? 3'd1 :
                   (run < 8'd8)   ? 3'd2 :
                   (run < 8'd16)  ? 3'd3 :
                   (run < 8'd32)  ? 3'd4 :
                   (run < 8'd64)  ? 3'd5 :
                   (run < 8'd128) ? 3'd6 : 3'd7;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      run    <= 8'd0;
      busy_q <= 1'b1;
      h1     <= 3'd0;
      h2     <= 3'd0;
      occ_q  <= 3'd0;
      wfi_q  <= 1'b0;
      evq_q  <= 4'd0;
    end else begin
      busy_q <= busy;
      occ_q  <= occ;
      wfi_q  <= wfi;
      evq_q  <= evq;
      if (busy) begin
        run <= 8'd0;
        if (!busy_q) begin          // an idle period just ended: record its length
          h2 <= h1;
          h1 <= run_bin;
        end
      end else if (run != 8'hFF) begin
        run <= run + 8'd1;
      end
    end
  end

  assign idle = (run > 8'd63) ? 6'd63 : run[5:0];
  assign feat = {busy, live, evq_q, wfi_q, occ_q, h2, h1, idle};
endmodule : ml_feature_block

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/pmu/pm_sense.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/pmu/pm_sense.sv
// Module    : pm_sense
// Content   : activity sensing per clock net for the PMU
//   cn_we  : functional write enables      -> clock-gating busy
//   cn_dem : present or in-flight demand   -> power-gating busy
//   occ    : pipeline occupancy (ML feature)
// Hierarchy : fido_top > u_sense
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module pm_sense
  import fido_pkg::*;
(
  // write enables (already isolated at their power-domain boundary)
  input  wire        we_add,
  input  wire        we_logic,
  input  wire        we_shift,
  input  wire        we_cmp,
  input  wire        we_mul,
  input  wire        we_div,
  input  wire        we_idex,
  input  wire        we_exmem,
  input  wire        we_memwb,
  input  wire  [3:0] dm_we,
  input  wire        rfh_we,
  input  wire        evq_busy,
  input  wire        we_core,
  // demand
  input  wire        id_vld,
  input  wire  [2:0] id_unit,
  input  wire        ex_vld,
  input  wire  [2:0] ex_unit,
  input  wire        mul_busy,
  input  wire        div_busy,
  input  wire        exmem_vld,
  input  wire        memwb_vld,
  input  wire  [3:0] bank_dem,
  input  wire        rfh_dem,
  input  wire        wfi_sleep,
  input  wire        evq_irq,
  // to PMU
  output logic [17:0] cn_we,
  output logic [17:0] cn_dem,
  output logic [2:0]  occ
);
  logic id_add;
  logic id_logic;
  logic id_shift;
  logic id_cmp;
  logic id_mul;
  logic id_div;

  //------------------------------------------------ clock-gating busy
  always_comb begin
    cn_we[CN_ADD_LO]  = we_add;
    cn_we[CN_ADD_HI]  = we_add;
    cn_we[CN_LOGIC_LO] = we_logic;
    cn_we[CN_LOGIC_HI] = we_logic;
    cn_we[CN_SHIFT]   = we_shift;
    cn_we[CN_CMP]     = we_cmp;
    cn_we[CN_MUL]     = we_mul;
    cn_we[CN_DIV]     = we_div;
    cn_we[CN_IDEX]    = we_idex;
    cn_we[CN_EXMEM]   = we_exmem;
    cn_we[CN_MEMWB]   = we_memwb;
    cn_we[CN_BANK0]   = dm_we[0];
    cn_we[CN_BANK1]   = dm_we[1];
    cn_we[CN_BANK2]   = dm_we[2];
    cn_we[CN_BANK3]   = dm_we[3];
    cn_we[CN_RFHI]    = rfh_we;
    cn_we[CN_EVQ]     = evq_busy;
    cn_we[CN_CORE]    = we_core;
  end

  //------------------------------------------------ power-gating busy (demand)
  assign id_add   = id_vld && (id_unit == FU_ADD);
  assign id_logic = id_vld && (id_unit == FU_LOGIC);
  assign id_shift = id_vld && (id_unit == FU_SHIFT);
  assign id_cmp   = id_vld && (id_unit == FU_CMP);
  assign id_mul   = id_vld && (id_unit == FU_MUL);
  assign id_div   = id_vld && (id_unit == FU_DIV);

  always_comb begin
    cn_dem[CN_ADD_LO]  = id_add   || (ex_unit == FU_ADD);
    cn_dem[CN_ADD_HI]  = id_add   || (ex_unit == FU_ADD);
    cn_dem[CN_LOGIC_LO] = id_logic || (ex_unit == FU_LOGIC);
    cn_dem[CN_LOGIC_HI] = id_logic || (ex_unit == FU_LOGIC);
    cn_dem[CN_SHIFT]   = id_shift || (ex_unit == FU_SHIFT);
    cn_dem[CN_CMP]     = id_cmp   || (ex_unit == FU_CMP);
    cn_dem[CN_MUL]     = id_mul   || (ex_unit == FU_MUL) || mul_busy;
    cn_dem[CN_DIV]     = id_div   || (ex_unit == FU_DIV) || div_busy;
    cn_dem[CN_IDEX]    = id_vld   || ex_vld;
    cn_dem[CN_EXMEM]   = exmem_vld || ex_vld;
    cn_dem[CN_MEMWB]   = memwb_vld || exmem_vld;
    cn_dem[CN_BANK0]   = bank_dem[0];
    cn_dem[CN_BANK1]   = bank_dem[1];
    cn_dem[CN_BANK2]   = bank_dem[2];
    cn_dem[CN_BANK3]   = bank_dem[3];
    cn_dem[CN_RFHI]    = rfh_dem;
    cn_dem[CN_EVQ]     = 1'b0;
    cn_dem[CN_CORE]    = !wfi_sleep || evq_irq;
  end

  //------------------------------------------------ pipeline occupancy
  assign occ = {2'b00, id_vld} + {2'b00, ex_vld} + {2'b00, exmem_vld} + {2'b00, memwb_vld};
endmodule : pm_sense

`default_nettype wire

