  wire [2:0] h1_1 = feat[38 +: 3];
  wire [2:0] h2_1 = feat[41 +: 3];
  wire [2:0] occ_1 = feat[44 +: 3];
  wire [0:0] wfi_1 = feat[47 +: 1];
  wire [3:0] evq_1 = feat[48 +: 4];
  wire [5:0] idle_2 = feat[64 +: 6];
