  wire [2:0] h2_2 = feat[73 +: 3];
  wire [2:0] occ_2 = feat[76 +: 3];
  wire [0:0] wfi_2 = feat[79 +: 1];
  wire [3:0] evq_2 = feat[80 +: 4];
  wire [5:0] idle_3 = feat[96 +: 6];
  wire [2:0] h1_3 = feat[102 +: 3];
  wire [2:0] h2_3 = feat[105 +: 3];
  wire [2:0] occ_3 = feat[108 +: 3];
  wire [0:0] wfi_3 = feat[111 +: 1];
  wire [3:0] evq_3 = feat[112 +: 4];
  wire [5:0] idle_4 = feat[128 +: 6];
  wire [2:0] h1_4 = feat[134 +: 3];
  wire [2:0] h2_4 = feat[137 +: 3];
  wire [2:0] occ_4 = feat[140 +: 3];
  wire [0:0] wfi_4 = feat[143 +: 1];
  wire [3:0] evq_4 = feat[144 +: 4];
  wire [5:0] idle_5 = feat[160 +: 6];
  wire [2:0] h1_5 = feat[166 +: 3];
  wire [2:0] h2_5 = feat[169 +: 3];
  wire [2:0] occ_5 = feat[172 +: 3];
  wire [0:0] wfi_5 = feat[175 +: 1];
  wire [3:0] evq_5 = feat[176 +: 4];
  wire [5:0] idle_6 = feat[192 +: 6];
  wire [2:0] h1_6 = feat[198 +: 3];
  wire [2:0] h2_6 = feat[201 +: 3];
  wire [2:0] occ_6 = feat[204 +: 3];
  wire [0:0] wfi_6 = feat[207 +: 1];
