    .clk     (clk),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .en      (data_en),
    .d       (d),
    .q       (q)
  );
endmodule : pipe_reg

