// >>> rtl/core/ex/alu_hi_unit.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/ex/alu_hi_unit.sv
// Module    : alu_hi_unit
// Content   : upper 16-bit halves of ADD/SUB and LOGIC; own operand registers (clock nets ADD_HI, LOGIC_HI); outputs isolated (clamp 0)
// Hierarchy : fido_top > u_core > u_ex > u_alu_hi
// Power leaf: ALU_HI (PD_ALU_HI in PG FINE)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module alu_hi_unit (
  input  wire        clk_add,
  input  wire        clk_logic,
  input  wire        rst_n,
  input  wire        pd_on,
  input  wire        pd_ret,
  input  wire        pd_init,
  input  wire        iso,
  input  wire        add_we,
  input  wire [15:0] add_a_d,
  input  wire [15:0] add_b_d,
  input  wire        logic_we,
  input  wire [15:0] logic_a_d,
  input  wire [15:0] logic_b_d,
  input  wire        a_fwd,
  input  wire [15:0] a_fwd_val,
  input  wire        b_fwd,
  input  wire [15:0] b_fwd_val,
  input  wire        sub,
  input  wire        cin,
  input  wire  [2:0] f3,
  output logic [15:0] add_res,
  output logic [15:0] logic_res
);
  wire  [15:0] add_a_q;
  wire  [15:0] add_b_q;
  wire  [15:0] lg_a_q;
  wire  [15:0] lg_b_q;
  logic [15:0] aa;
  logic [15:0] ab;
  logic [15:0] la;
  logic [15:0] lb;
  logic [15:0] abx;
  logic [15:0] sum;
  logic [15:0] lres;

  pg_dff #(.W(32)) u_add_ops (
    .clk     (clk_add),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .en      (add_we),
    .d       ({add_a_d, add_b_d}),
    .q       ({add_a_q, add_b_q})
  );

  pg_dff #(.W(32)) u_logic_ops (
    .clk     (clk_logic),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .en      (logic_we),
    .d       ({logic_a_d, logic_b_d}),
    .q       ({lg_a_q, lg_b_q})
  );

  assign aa   = a_fwd ? a_fwd_val : add_a_q;
  assign ab   = b_fwd ? b_fwd_val : add_b_q;
  assign la   = a_fwd ? a_fwd_val : lg_a_q;
  assign lb   = b_fwd ? b_fwd_val : lg_b_q;
  assign abx  = sub ? ~ab : ab;
  assign sum  = aa + abx + {15'd0, cin};
  assign lres = (f3 == 3'b100) ? (la ^ lb) :
                (f3 == 3'b110) ? (la | lb) : (la & lb);

  // isolation cells on the ALU_HI boundary
  iso_clamp #(.W(16), .CLAMP(16'd0)) u_iso_add (.iso(iso), .d(sum), .q(add_res));
  iso_clamp #(.W(16), .CLAMP(16'd0)) u_iso_logic (.iso(iso), .d(lres), .q(logic_res));
endmodule : alu_hi_unit

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/ex/alu_shift.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/ex/alu_shift.sv
// Module    : alu_shift
// Content   : barrel shifter SLL/SRL/SRA: own operand registers (clock net SHIFT)
// Hierarchy : fido_top > u_core > u_ex > u_shift
// Power leaf: EX (clock net SHIFT)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module alu_shift (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        pd_on,
  input  wire        pd_ret,
  input  wire        pd_init,
  input  wire        we,
  input  wire [31:0] a_d,
  input  wire  [4:0] b_d,
  input  wire        a_fwd,
  input  wire [31:0] a_fwd_val,
  input  wire        b_fwd,
  input  wire  [4:0] b_fwd_val,
  input  wire  [2:0] f3,
  input  wire        sra,           // arithmetic right shift (SRA / SRAI)
  output logic [31:0] res
);
  wire  [31:0] a_q;
  wire  [4:0]  b_q;
  logic [31:0] a;
  logic [4:0]  b;
  logic [31:0] r_sra;

  pg_dff #(.W(37)) u_ops (
    .clk     (clk),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .en      (we),
    .d       ({a_d, b_d}),
    .q       ({a_q, b_q})
  );

  assign a     = a_fwd ? a_fwd_val : a_q;
  assign b     = b_fwd ? b_fwd_val : b_q;
  assign r_sra = $signed(a) >>> b;
  assign res   = (f3 == 3'b001) ? (a << b) :
                 sra            ? r_sra    : (a >> b);
endmodule : alu_shift

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/ex/alu_cmp.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/ex/alu_cmp.sv
// Module    : alu_cmp
// Content   : comparator: SLT/SLTU result and branch condition; own operand registers (clock net CMP)
// Hierarchy : fido_top > u_core > u_ex > u_cmp
// Power leaf: EX (clock net CMP)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module alu_cmp (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        pd_on,
  input  wire        pd_ret,
  input  wire        pd_init,
  input  wire        we,
  input  wire [31:0] a_d,
  input  wire [31:0] b_d,
  input  wire        a_fwd,
  input  wire [31:0] a_fwd_val,
  input  wire        b_fwd,
  input  wire [31:0] b_fwd_val,
  input  wire  [2:0] f3,
  output logic        slt_bit,
  output logic        br_cond
);
  wire  [31:0] a_q;
  wire  [31:0] b_q;
  logic [31:0] a;
  logic [31:0] b;
  logic        c_eq;
  logic        c_lt;
  logic        c_ltu;

  pg_dff #(.W(64)) u_ops (
    .clk     (clk),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .en      (we),
    .d       ({a_d, b_d}),
    .q       ({a_q, b_q})
  );

  assign a       = a_fwd ? a_fwd_val : a_q;
  assign b       = b_fwd ? b_fwd_val : b_q;
  assign c_eq    = (a == b);
  assign c_lt    = ($signed(a) < $signed(b));
  assign c_ltu   = (a < b);
  assign slt_bit = (f3 == 3'b011) ? c_ltu : c_lt;

  always_comb begin
    case (f3)
      3'b000:  br_cond = c_eq;
      3'b001:  br_cond = ~c_eq;
      3'b100:  br_cond = c_lt;
      3'b101:  br_cond = ~c_lt;
      3'b110:  br_cond = c_ltu;
      3'b111:  br_cond = ~c_ltu;
      default: br_cond = 1'b0;
    endcase
  end
endmodule : alu_cmp

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/ex/mul_unit.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/ex/mul_unit.sv
// Module    : mul_unit
// Content   : 3-stage pipelined multiplier. op: 00 MUL, 01 MULH, 10 MULHSU, 11 MULHU. Stage 1 latches the sign-extended operands, stage 2 forms the 64-bit product, stage 3 selects the half; done = 1 three cycles after start. Outputs isolated (clamp 0).
// Hierarchy : fido_top > u_core > u_ex > u_mul
// Power leaf: MUL (clock net MUL, PD_MUL in PG FINE)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module mul_unit (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        pd_on,
  input  wire        pd_ret,
  input  wire        pd_init,
  input  wire        iso,
  input  wire        start,
  input  wire  [1:0] op,
  input  wire [31:0] a,
  input  wire [31:0] b,
  output logic        busy,
  output logic        done,
  output logic [31:0] res,
  output logic        we
);
  // state = {v1, a1[32:0], b1[32:0], op1[1:0], v2, p2[63:0], op2[1:0], v3, r3[31:0]}
  wire        v1;
  wire [32:0] a1;
  wire [32:0] b1;
  wire [1:0]  op1;
  wire        v2;
  wire [63:0] p2;
  wire [1:0]  op2;
  wire        v3;
  wire [31:0] r3;

  logic               a_sgn;
  logic               b_sgn;
  logic signed [65:0] prod;
  logic               n_v1;
  logic [32:0]        n_a1;
  logic [32:0]        n_b1;
  logic [1:0]         n_op1;
  logic               n_v2;
  logic [63:0]        n_p2;
  logic [1:0]         n_op2;
  logic               n_v3;
  logic [31:0]        n_r3;
  logic               en;

  assign a_sgn = (op == 2'b01) || (op == 2'b10);
  assign b_sgn = (op == 2'b01);
  assign prod  = $signed(a1) * $signed(b1);

  assign n_v1  = start;
  assign n_a1  = start ? {a_sgn & a[31], a} : a1;
  assign n_b1  = start ? {b_sgn & b[31], b} : b1;
  assign n_op1 = start ? op : op1;
  assign n_v2  = v1;
  assign n_p2  = v1 ? prod[63:0] : p2;
  assign n_op2 = v1 ? op1 : op2;
  assign n_v3  = v2;
  assign n_r3  = v2 ? ((op2 == 2'b00) ? p2[31:0] : p2[63:32]) : r3;
  assign en    = start | v1 | v2 | v3;

  pg_dff #(.W(169)) u_state (
    .clk     (clk),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .en      (en),
    .d       ({n_v1, n_a1, n_b1, n_op1, n_v2, n_p2, n_op2, n_v3, n_r3}),
    .q       ({v1, a1, b1, op1, v2, p2, op2, v3, r3})
  );

  // isolation cells on the MUL boundary
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_busy (.iso(iso), .d((v1 | v2 | v3)), .q(busy));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_done (.iso(iso), .d(v3), .q(done));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_res (.iso(iso), .d(r3), .q(res));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_we (.iso(iso), .d(en), .q(we));
endmodule : mul_unit

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/ex/div_unit.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/ex/div_unit.sv
// Module    : div_unit
// Content   : iterative restoring divider, 32 iterations. op: 00 DIV, 01 DIVU, 10 REM, 11 REMU (RISC-V divide-by-zero semantics). Outputs isolated (clamp 0).
// Hierarchy : fido_top > u_core > u_ex > u_div
// Power leaf: DIV (clock net DIV, PD_DIV in PG FINE)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module div_unit (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        pd_on,
  input  wire        pd_ret,
  input  wire        pd_init,
  input  wire        iso,
  input  wire        start,
  input  wire  [1:0] op,
  input  wire [31:0] a,
  input  wire [31:0] b,
  output logic        busy,
  output logic        done,
  output logic [31:0] res,
  output logic        we
);
  // state = {bsy, cnt[5:0], rem[31:0], quo[31:0], dvs[31:0], negq, negr, isrem, dn, r[31:0]}
  wire        bsy;
  wire [5:0]  cnt;
  wire [31:0] rem;
  wire [31:0] quo;
  wire [31:0] dvs;
  wire        negq;
  wire        negr;
  wire        isrem;
  wire        dn;
  wire [31:0] r;

  logic        sgn;
  logic        a_neg;
  logic        b_neg;
  logic [31:0] a_abs;
  logic [31:0] b_abs;
  logic        b_zero;
  logic [32:0] rs;
  logic [33:0] diff;
  logic        ge;
  logic [31:0] q_fin;
  logic [31:0] r_fin;
  logic        en;

  logic        n_bsy;
  logic [5:0]  n_cnt;
  logic [31:0] n_rem;
  logic [31:0] n_quo;
  logic [31:0] n_dvs;
  logic        n_negq;
  logic        n_negr;
  logic        n_isrem;
  logic        n_dn;
  logic [31:0] n_r;

  assign sgn    = ~op[0];
  assign a_neg  = sgn & a[31];
  assign b_neg  = sgn & b[31];
  assign a_abs  = a_neg ? (~a + 32'd1) : a;
  assign b_abs  = b_neg ? (~b + 32'd1) : b;
  assign b_zero = (b == 32'd0);
  assign rs     = {rem, quo[31]};
  assign diff   = {1'b0, rs} - {2'b00, dvs};
  assign ge     = ~diff[33];
  assign q_fin  = negq ? (~quo + 32'd1) : quo;
  assign r_fin  = negr ? (~rem + 32'd1) : rem;

  always_comb begin
    n_bsy   = bsy;
    n_cnt   = cnt;
    n_rem   = rem;
    n_quo   = quo;
    n_dvs   = dvs;
    n_negq  = negq;
    n_negr  = negr;
    n_isrem = isrem;
    n_dn    = 1'b0;
    n_r     = r;
    if (start) begin
      if (b_zero) begin
        n_bsy = 1'b0;
        n_dn  = 1'b1;
        n_r   = op[1] ? a : 32'hFFFF_FFFF;
      end else begin
        n_bsy   = 1'b1;
        n_cnt   = 6'd32;
        n_rem   = 32'd0;
        n_quo   = a_abs;
        n_dvs   = b_abs;
        n_negq  = a_neg ^ b_neg;
        n_negr  = a_neg;
        n_isrem = op[1];
      end
    end else if (bsy) begin
      if (cnt != 6'd0) begin
        n_cnt = cnt - 6'd1;
        if (ge) begin
          n_rem = diff[31:0];
          n_quo = {quo[30:0], 1'b1};
        end else begin
          n_rem = rs[31:0];
          n_quo = {quo[30:0], 1'b0};
        end
      end else begin
        n_bsy = 1'b0;
        n_dn  = 1'b1;
        n_r   = isrem ? r_fin : q_fin;
      end
    end
  end

  assign en = start | bsy | dn;

  pg_dff #(.W(139)) u_state (
    .clk     (clk),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .en      (en),
    .d       ({n_bsy, n_cnt, n_rem, n_quo, n_dvs, n_negq, n_negr, n_isrem, n_dn, n_r}),
    .q       ({bsy, cnt, rem, quo, dvs, negq, negr, isrem, dn, r})
  );

  // isolation cells on the DIV boundary
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_busy (.iso(iso), .d(bsy), .q(busy));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_done (.iso(iso), .d(dn), .q(done));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_res (.iso(iso), .d(r), .q(res));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_we (.iso(iso), .d(en), .q(we));
endmodule : div_unit

`default_nettype wire

