  output logic [31:0] ex_insn,
  output logic  [4:0] ex_rd,
  output logic        ex_wen,
  output logic [31:0] ex_res,
  output logic        ex_load,
  output logic        ex_store,
  output logic  [2:0] ex_f3,
  output logic [31:0] ex_addr,
  output logic [31:0] ex_sdata,
