    .rst_n   (rst_n),
    .pd_on   (pdx_on),
    .pd_ret  (pdx_ret),
    .pd_init (pdx_init),
    .vld_en  (idex_vld_we),
    .vld_d   (id_load),
    .data_en (id_load),
    .d       ({id_pc, id_insn, id_imm, id_r1, id_r2, id_rd, id_rs1, id_rs2, id_ctl}),
    .vld_q   (q_vld),
    .q       ({q_pc, q_insn, q_imm, q_r1, q_r2, q_rd, q_rs1, q_rs2, q_ctl_w})
