    .urs2        (q_ctl.urs2),
    .rs1         (q_rs1),
    .rs2         (q_rs2),
    .exmem_vld   (fw_exmem_vld),
    .exmem_wen   (fw_exmem_wen),
    .exmem_rd    (fw_exmem_rd),
    .exmem_res   (fw_exmem_res),
    .memwb_vld   (fw_memwb_vld),
    .memwb_wen   (fw_memwb_wen),
    .memwb_rd    (fw_memwb_rd),
    .memwb_wdata (fw_memwb_wdata),
    .fa          (fa),
    .fb          (fb),
    .fa_val      (fa_val),
    .fb_val      (fb_val)
  );

  assign a_full = fa ? fa_val : q_r1;
  assign b_full = fb ? fb_val : q_r2;

  //================================================================ operand dispatch
  // the operand registers of a sub-unit load only when an instruction for
  // that unit issues, so idle sub-units see no write enable (clock gating)
  logic [31:0] id_a;
  logic [31:0] id_b;
  logic        op_we_add;
  logic        op_we_logic;
  logic        op_we_shift;
  logic        op_we_cmp;
  logic        is_sub;

  assign id_a        = id_r1;
  assign id_b        = id_ctl.bimm ? id_imm : id_r2;
  assign op_we_add   = id_load && (id_unit == FU_ADD);
  assign op_we_logic = id_load && (id_unit == FU_LOGIC);
  assign op_we_shift = id_load && (id_unit == FU_SHIFT);
  assign op_we_cmp   = id_load && (id_unit == FU_CMP);
  assign is_sub      = q_ctl.sub && (unit == FU_ADD);

  //================================================================ ALU sub-units
  wire [16:0] sum_lo;
  wire [15:0] lg_lo;
  wire [15:0] add_hi;
  wire [15:0] lg_hi;
  wire [31:0] shift_res;
  wire        slt_bit;
  wire        br_cond;
  logic [31:0] add_res;
  logic [31:0] logic_res;

  alu_addsub u_addsub (
    .clk       (clk_add_lo),
    .rst_n     (rst_n),
    .pd_on     (pdx_on),
    .pd_ret    (pdx_ret),
    .pd_init   (pdx_init),
    .we        (op_we_add),
    .a_d       (id_a[15:0]),
    .b_d       (id_b[15:0]),
    .a_fwd     (fa),
    .a_fwd_val (fa_val[15:0]),
    .b_fwd     (fb),
    .b_fwd_val (fb_val[15:0]),
    .sub       (is_sub),
    .sum_lo    (sum_lo)
  );

  alu_logic u_logic (
    .clk       (clk_logic_lo),
    .rst_n     (rst_n),
    .pd_on     (pdx_on),
    .pd_ret    (pdx_ret),
    .pd_init   (pdx_init),
    .we        (op_we_logic),
    .a_d       (id_a[15:0]),
    .b_d       (id_b[15:0]),
    .a_fwd     (fa),
    .a_fwd_val (fa_val[15:0]),
    .b_fwd     (fb),
    .b_fwd_val (fb_val[15:0]),
    .f3        (f3),
    .res_lo    (lg_lo)
  );

  alu_hi_unit u_alu_hi (
    .clk_add   (clk_add_hi),
    .clk_logic (clk_logic_hi),
    .rst_n     (rst_n),
    .pd_on     (pdh_on),
    .pd_ret    (pdh_ret),
    .pd_init   (pdh_init),
    .iso       (pdh_iso),
    .add_we    (op_we_add),
    .add_a_d   (id_a[31:16]),
    .add_b_d   (id_b[31:16]),
    .logic_we  (op_we_logic),
    .logic_a_d (id_a[31:16]),
    .logic_b_d (id_b[31:16]),
    .a_fwd     (fa),
    .a_fwd_val (fa_val[31:16]),
    .b_fwd     (fb),
    .b_fwd_val (fb_val[31:16]),
    .sub       (is_sub),
    .cin       (sum_lo[16]),
    .f3        (f3),
    .add_res   (add_hi),
    .logic_res (lg_hi)
  );

  alu_shift u_shift (
    .clk       (clk_shift),
    .rst_n     (rst_n),
    .pd_on     (pdx_on),
    .pd_ret    (pdx_ret),
    .pd_init   (pdx_init),
    .we        (op_we_shift),
    .a_d       (id_a),
    .b_d       (id_b[4:0]),
    .a_fwd     (fa),
    .a_fwd_val (fa_val),
    .b_fwd     (fb),
    .b_fwd_val (fb_val[4:0]),
    .f3        (f3),
    .sra       (q_ctl.sub),
    .res       (shift_res)
  );

  alu_cmp u_cmp (
    .clk       (clk_cmp),
    .rst_n     (rst_n),
    .pd_on     (pdx_on),
    .pd_ret    (pdx_ret),
    .pd_init   (pdx_init),
    .we        (op_we_cmp),
    .a_d       (id_a),
    .b_d       (id_b),
    .a_fwd     (fa),
    .a_fwd_val (fa_val),
    .b_fwd     (fb),
    .b_fwd_val (fb_val),
    .f3        (f3),
    .slt_bit   (slt_bit),
    .br_cond   (br_cond)
  );

  assign add_res   = {add_hi, sum_lo[15:0]};
  assign logic_res = {lg_hi, lg_lo};

  //================================================================ MUL / DIV
  wire        start_mdu;
  wire        mdu_started;
  wire        flags_en;
  wire [31:0] mdu_out;
  wire        stall_i;
  wire        mul_done;
  wire [31:0] mul_res;
  wire        div_done;
  wire [31:0] div_res;
  wire        mul_busy_i;
  wire        div_busy_i;
  wire        mul_we_i;
  wire        div_we_i;

  mdu_ctrl u_mdu (
    .clk         (clk_idex),
    .rst_n       (rst_n),
    .pd_on       (pdx_on),
    .pd_ret      (pdx_ret),
    .pd_init     (pdx_init),
    .q_vld       (q_vld),
    .is_mul      (is_mul),
    .is_div      (is_div),
    .take_trap   (take_trap),
    .ex_adv      (ex_adv),
    .mul_done    (mul_done),
    .mul_res     (mul_res),
    .div_done    (div_done),
    .div_res     (div_res),
    .start_mdu   (start_mdu),
    .mdu_started (mdu_started),
    .flags_en    (flags_en),
    .mdu_out     (mdu_out),
    .stall       (stall_i)
  );

  mul_unit u_mul (
    .clk     (clk_mul),
    .rst_n   (rst_n),
    .pd_on   (pdm_on),
    .pd_ret  (pdm_ret),
    .pd_init (pdm_init),
    .iso     (pdm_iso),
    .start   (start_mdu && is_mul),
    .op      (f3[1:0]),
    .a       (a_full),
    .b       (b_full),
    .busy    (mul_busy_i),
    .done    (mul_done),
    .res     (mul_res),
    .we      (mul_we_i)
  );

  div_unit u_div (
    .clk     (clk_div),
    .rst_n   (rst_n),
    .pd_on   (pdd_on),
    .pd_ret  (pdd_ret),
    .pd_init (pdd_init),
    .iso     (pdd_iso),
    .start   (start_mdu && is_div),
    .op      (f3[1:0]),
    .a       (a_full),
    .b       (b_full),
    .busy    (div_busy_i),
    .done    (div_done),
    .res     (div_res),
    .we      (div_we_i)
  );

  //================================================================ result, branch, AGU
  logic [31:0] pc_imm;
  logic [31:0] pc_4;
  logic [31:0] agu;
  logic [31:0] res_i;
  logic        redir_i;
  logic [31:0] target_i;
  logic        exc_i;
  logic  [3:0] code_i;
  logic [31:0] csrsrc_i;

  assign pc_imm = q_pc + q_imm;
  assign pc_4   = q_pc + 32'd4;
  assign agu    = a_full + q_imm;

  always_comb begin
    if (q_ctl.lui)                    res_i = q_imm;
    else if (q_ctl.auipc)             res_i = pc_imm;
    else if (q_ctl.jal || q_ctl.jalr) res_i = pc_4;
    else if (q_ctl.csr)               res_i = csr_rdata;
    else begin
      case (unit)
        FU_ADD:   res_i = add_res;
        FU_SHIFT: res_i = shift_res;
        FU_LOGIC: res_i = logic_res;
        FU_CMP:   res_i = {31'd0, slt_bit};
        FU_MUL:   res_i = mdu_out;
        FU_DIV:   res_i = mdu_out;
        default:  res_i = 32'd0;
      endcase
    end
  end

  assign redir_i  = q_vld && ((q_ctl.br && br_cond) || q_ctl.jal || q_ctl.jalr);
  assign target_i = q_ctl.jalr ? {agu[31:1], 1'b0} : pc_imm;
  assign exc_i    = q_vld && (q_ctl.ecall || q_ctl.ebreak || q_ctl.ill);
  assign code_i   = q_ctl.ill ? 4'd2 : (q_ctl.ebreak ? 4'd3 : 4'd11);
  assign csrsrc_i = f3[2] ? {27'd0, q_rs1} : a_full;

  //================================================================ isolation (EX boundary)
  // one isolation cell per output signal (clamp 0), as UPF set_isolation would place them
  // pipeline data to MEM
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_vld (.iso(pdx_iso), .d(q_vld), .q(ex_vld));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_ex_pc (.iso(pdx_iso), .d(q_pc), .q(ex_pc));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_ex_insn (.iso(pdx_iso), .d(q_insn), .q(ex_insn));
  iso_clamp #(.W(5), .CLAMP(5'd0)) u_iso_ex_rd (.iso(pdx_iso), .d(q_rd), .q(ex_rd));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_wen (.iso(pdx_iso), .d(q_ctl.wen), .q(ex_wen));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_ex_res (.iso(pdx_iso), .d(res_i), .q(ex_res));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_load (.iso(pdx_iso), .d(q_ctl.load), .q(ex_load));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_store (.iso(pdx_iso), .d(q_ctl.store), .q(ex_store));
  iso_clamp #(.W(3), .CLAMP(3'd0)) u_iso_ex_f3 (.iso(pdx_iso), .d(f3), .q(ex_f3));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_ex_addr (.iso(pdx_iso), .d(agu), .q(ex_addr));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_ex_sdata (.iso(pdx_iso), .d(b_full), .q(ex_sdata));
  // control to IF / trap / CSR
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_redirect (.iso(pdx_iso), .d(redir_i), .q(ex_redirect));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_ex_target (.iso(pdx_iso), .d(target_i), .q(ex_target));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_exc (.iso(pdx_iso), .d(exc_i), .q(ex_exc));
  iso_clamp #(.W(4), .CLAMP(4'd0)) u_iso_ex_exc_code (.iso(pdx_iso), .d(code_i), .q(ex_exc_code));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_mret (.iso(pdx_iso), .d((q_vld && q_ctl.mret)), .q(ex_mret));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_wfi (.iso(pdx_iso), .d((q_vld && q_ctl.wfi)), .q(ex_wfi));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_csr (.iso(pdx_iso), .d((q_vld && q_ctl.csr)), .q(ex_csr));
  iso_clamp #(.W(12), .CLAMP(12'd0)) u_iso_ex_csr_addr (.iso(pdx_iso), .d(q_insn[31:20]), .q(ex_csr_addr));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_ex_csr_src (.iso(pdx_iso), .d(csrsrc_i), .q(ex_csr_src));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_csr_wnz (.iso(pdx_iso), .d((q_rs1 != 5'd0)), .q(ex_csr_wnz));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_stall (.iso(pdx_iso), .d(stall_i), .q(ex_stall));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_mdu_started (.iso(pdx_iso), .d(mdu_started), .q(ex_mdu_started));
  // PMU sensing
  iso_clamp #(.W(3), .CLAMP(3'd0)) u_iso_ex_unit (.iso(pdx_iso), .d((q_vld ? unit : FU_NONE)), .q(ex_unit));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_mul_busy (.iso(pdx_iso), .d(mul_busy_i), .q(mul_busy));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_div_busy (.iso(pdx_iso), .d(div_busy_i), .q(div_busy));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_we_add (.iso(pdx_iso), .d(op_we_add), .q(we_add));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_we_logic (.iso(pdx_iso), .d(op_we_logic), .q(we_logic));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_we_shift (.iso(pdx_iso), .d(op_we_shift), .q(we_shift));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_we_cmp (.iso(pdx_iso), .d(op_we_cmp), .q(we_cmp));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_we_mul (.iso(pdx_iso), .d(mul_we_i), .q(we_mul));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_we_div (.iso(pdx_iso), .d(div_we_i), .q(we_div));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_we_idex (.iso(pdx_iso), .d((id_load | idex_vld_we | flags_en)), .q(we_idex));
endmodule : ex_stage

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/if_stage.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/if_stage.sv
// Module    : if_stage
// Content   : IF stage: PC (retention flop) and the IF/ID register; fetch stops while the core sleeps in WFI
// Hierarchy : fido_top > u_core (rv32im_core) > u_if
// Power leaf: CORE (clock net CORE)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module if_stage (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        pd_on,
  input  wire        pd_ret,
  input  wire        pd_init,
  input  wire        flush,          // redirect from EX (branch, jump, trap, mret, wfi)
  input  wire [31:0] flush_target,
  input  wire        id_issue,       // IF/ID content moves to ID/EX this cycle
  input  wire        wfi_flag,       // core asleep: no fetch
  input  wire [31:0] imem_rdata,
  output logic [31:0] pc,
  output logic        ifid_vld,
  output logic [31:0] ifid_pc,
  output logic [31:0] ifid_insn,
  output logic        we             // any IF register written (clock-gating busy)
);
  logic        fetch_ok;
  logic        ifid_free;
  logic        pc_en;
  logic [31:0] pc_d;
  logic        ifid_vld_en;
  logic        ifid_vld_d;
  logic        ifid_data_en;

  assign fetch_ok     = !wfi_flag;
  assign ifid_free    = !ifid_vld || id_issue;
  assign pc_en        = flush || (ifid_free && fetch_ok);
  assign pc_d         = flush ? flush_target : (pc + 32'd4);
  assign ifid_vld_en  = flush || (ifid_free && (fetch_ok || ifid_vld));
  assign ifid_vld_d   = !flush && fetch_ok;
  assign ifid_data_en = !flush && ifid_free && fetch_ok;

  pg_dff #(.W(32), .RV(32'd0), .RET(1)) u_pc (
    .clk     (clk),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .en      (pc_en),
    .d       (pc_d),
    .q       (pc)
  );

  pipe_reg #(.W(64)) u_ifid (
    .clk     (clk),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .vld_en  (ifid_vld_en),
    .vld_d   (ifid_vld_d),
    .data_en (ifid_data_en),
    .d       ({pc, imem_rdata}),
    .vld_q   (ifid_vld),
    .q       ({ifid_pc, ifid_insn})
  );

  assign we = pc_en || ifid_vld_en || ifid_data_en;
endmodule : if_stage

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/id_stage.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/id_stage.sv
// Module    : id_stage
// Content   : ID stage: RV32IM decoder (fido_pkg::decode), immediate generator, register specifiers, RF-HI use flag
// Hierarchy : fido_top > u_core (rv32im_core) > u_id
// Power leaf: CORE (combinational)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module id_stage
  import fido_pkg::*;
(
  input  wire  [31:0] ifid_insn,
  output ctl_t        ctl,
  output logic [31:0] imm,
  output logic  [4:0] rs1,
  output logic  [4:0] rs2,
  output logic  [4:0] rd,
  output logic  [2:0] unit,
  output logic        uses_hi      // touches x16..x31 (RF-HI bank)
);
  assign ctl     = decode(ifid_insn);
  assign imm     = immgen(ifid_insn);
  assign rs1     = ifid_insn[19:15];
  assign rs2     = ifid_insn[24:20];
  assign rd      = ifid_insn[11:7];
  assign unit    = ctl.unit;
  assign uses_hi = (ctl.urs1 && rs1[4]) || (ctl.urs2 && rs2[4]) || (ctl.wen && rd[4]);
endmodule : id_stage

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/rf_bank.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/rf_bank.sv
// Module    : rf_bank
// Content   : one register-file bank, 16 x 32, 2R1W, asynchronous read, retention array (keeps its content while off only if pd_ret was raised first); read data isolated (clamp 0)
// Hierarchy : fido_top > u_core > u_rf > u_bank_lo / u_bank_hi
// Power leaf: CORE (u_bank_lo, iso tied 0) or RF_HI (u_bank_hi)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module rf_bank (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        pd_on,
  input  wire        pd_ret,
  input  wire        iso,
  input  wire  [3:0] ra1,
  input  wire  [3:0] ra2,
  input  wire        we,
  input  wire  [3:0] wa,
  input  wire [31:0] wd,
  output logic [31:0] rd1,
  output logic [31:0] rd2
);
  logic [31:0] mem [16];

  always_ff @(posedge clk or negedge rst_n or negedge pd_on) begin
    if (!rst_n) begin
      for (int i = 0; i < 16; i++) mem[i] <= 32'd0;
    end else if (!pd_on) begin
      if (!pd_ret) begin
        for (int i = 0; i < 16; i++) mem[i] <= 'x;
      end
    end else if (we) begin
      mem[wa] <= wd;
    end
  end

  logic [31:0] r1;
  logic [31:0] r2;

  assign r1 = mem[ra1];
  assign r2 = mem[ra2];

  // isolation cells on the read ports (clamp 0)
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_rd1 (.iso(iso), .d(r1), .q(rd1));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_rd2 (.iso(iso), .d(r2), .q(rd2));
endmodule : rf_bank

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/regfile.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/regfile.sv
// Module    : regfile
// Content   : register file x0..x31 in two banks: u_bank_lo (x0..x15, CORE leaf) and u_bank_hi (x16..x31, RF-HI leaf, behind isolation cells in both directions); x0 hard-wired to 0; write-back bypass to the ID read ports
// Hierarchy : fido_top > u_core (rv32im_core) > u_rf
// Power leaf: CORE (u_bank_lo, read mux) and RF_HI (u_bank_hi, clock net RFHI)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module regfile (
  input  wire        clk_lo,         // clock net CORE
  input  wire        clk_hi,         // clock net RFHI
  input  wire        rst_n,
  // power leaf CORE
  input  wire        pdc_on,
  input  wire        pdc_ret,
  input  wire        pdc_iso,
  // power leaf RF_HI
  input  wire        pdh_on,
  input  wire        pdh_ret,
  input  wire        pdh_iso,
  // read (ID)
  input  wire  [4:0] rs1,
  input  wire  [4:0] rs2,
  // write (WB)
  input  wire        wb_we,
  input  wire  [4:0] wb_rd,
  input  wire [31:0] wb_wdata,
  output logic [31:0] r1,
  output logic [31:0] r2,
  output logic        rflo_we,       // bank LO written (clock-gating busy of CORE)
  output logic        rfh_we         // bank HI written, isolated (clock-gating busy of RFHI)
);
  wire [31:0] lo_rd1;
  wire [31:0] lo_rd2;
  wire [31:0] hi_rd1;
  wire [31:0] hi_rd2;
  wire  [3:0] hi_ra1;
  wire  [3:0] hi_ra2;
  wire        hi_we;
  wire  [3:0] hi_wa;
  wire [31:0] hi_wd;
  logic       rfh_we_i;
  logic [31:0] rd1_raw;
  logic [31:0] rd2_raw;

  assign rflo_we  = wb_we && !wb_rd[4];
  assign rfh_we_i = wb_we && wb_rd[4];

  //------------------------------------------------ bank LO (inside the CORE leaf)
  rf_bank u_bank_lo (
    .clk    (clk_lo),
    .rst_n  (rst_n),
    .pd_on  (pdc_on),
    .pd_ret (pdc_ret),
    .iso    (1'b0),
    .ra1    (rs1[3:0]),
    .ra2    (rs2[3:0]),
    .we     (rflo_we),
    .wa     (wb_rd[3:0]),
    .wd     (wb_wdata),
    .rd1    (lo_rd1),
    .rd2    (lo_rd2)
  );

  //------------------------------------------------ CORE -> RF-HI isolation (clamp 0)
  iso_clamp #(.W(4), .CLAMP(4'd0)) u_iso_hi_ra1 (.iso(pdc_iso), .d(rs1[3:0]), .q(hi_ra1));
  iso_clamp #(.W(4), .CLAMP(4'd0)) u_iso_hi_ra2 (.iso(pdc_iso), .d(rs2[3:0]), .q(hi_ra2));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_hi_we (.iso(pdc_iso), .d(rfh_we_i), .q(hi_we));
  iso_clamp #(.W(4), .CLAMP(4'd0)) u_iso_hi_wa (.iso(pdc_iso), .d(wb_rd[3:0]), .q(hi_wa));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_hi_wd (.iso(pdc_iso), .d(wb_wdata), .q(hi_wd));

  //------------------------------------------------ bank HI (RF-HI leaf, isolated read data)
  rf_bank u_bank_hi (
    .clk    (clk_hi),
    .rst_n  (rst_n),
    .pd_on  (pdh_on),
    .pd_ret (pdh_ret),
    .iso    (pdh_iso),
    .ra1    (hi_ra1),
    .ra2    (hi_ra2),
    .we     (hi_we),
    .wa     (hi_wa),
    .wd     (hi_wd),
    .rd1    (hi_rd1),
    .rd2    (hi_rd2)
  );

  //------------------------------------------------ read ports: bank select, x0, WB bypass
  assign rd1_raw = rs1[4] ? hi_rd1 : lo_rd1;
  assign rd2_raw = rs2[4] ? hi_rd2 : lo_rd2;
  assign r1      = (rs1 == 5'd0) ? 32'd0 : ((wb_we && (wb_rd == rs1)) ? wb_wdata : rd1_raw);
  assign r2      = (rs2 == 5'd0) ? 32'd0 : ((wb_we && (wb_rd == rs2)) ? wb_wdata : rd2_raw);
  assign rfh_we  = hi_we;
endmodule : regfile

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/hazard_unit.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/hazard_unit.sv
// Module    : hazard_unit
// Content   : pipeline hazards: load-use interlock, domain readiness (a gated unit must be awake before issue), EX hold, issue and gating-stall accounting
// Hierarchy : fido_top > u_core (rv32im_core) > u_hz
// Power leaf: CORE (combinational)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module hazard_unit
  import fido_pkg::*;
(
  input  wire        ifid_vld,
  input  wire        urs1,           // instruction in ID uses rs1
  input  wire        urs2,           // instruction in ID uses rs2
  input  wire  [4:0] rs1,
  input  wire  [4:0] rs2,
  input  wire  [2:0] unit,
  input  wire        uses_hi,
  input  wire        ex_vld,
  input  wire        ex_load,
  input  wire  [4:0] ex_rd,
  input  wire        ex_stall,       // EX busy with a MUL / DIV
  input  wire        mem_stall,      // MEM waits for a waking bank
  input  wire        flush,
  input  wire [17:0] cn_ready,       // per clock net: domain ready (not power-gated)
  output logic       ex_adv,         // EX instruction advances this cycle
  output logic       id_issue,       // ID instruction issues this cycle
  output logic       idex_vld_we,    // ID/EX valid flop must be written
  output logic       pg_stall        // stall cycle caused by gating
);
  logic unit_rdy;
  logic load_use;
  logic res_stall;      // the unit (or ID/EX, RF-HI) is not ready
  logic ex_hold;
  logic id_stall;

  assign load_use = ex_vld && ex_load && (ex_rd != 5'd0) &&
                    ((urs1 && (rs1 == ex_rd)) || (urs2 && (rs2 == ex_rd)));

  always_comb begin
    case (unit)
      FU_ADD:   unit_rdy = cn_ready[CN_ADD_LO] & cn_ready[CN_ADD_HI];
      FU_SHIFT: unit_rdy = cn_ready[CN_SHIFT];
      FU_LOGIC: unit_rdy = cn_ready[CN_LOGIC_LO] & cn_ready[CN_LOGIC_HI];
      FU_CMP:   unit_rdy = cn_ready[CN_CMP];
      FU_MUL:   unit_rdy = cn_ready[CN_MUL];
      FU_DIV:   unit_rdy = cn_ready[CN_DIV];
      default:  unit_rdy = 1'b1;
    endcase
  end

  assign res_stall   = !(unit_rdy && cn_ready[CN_IDEX] && (!uses_hi || cn_ready[CN_RFHI]));
  assign id_stall    = ifid_vld && (load_use || res_stall);
  assign ex_hold     = (ex_vld && ex_stall) || mem_stall;
  assign ex_adv      = ex_vld && !ex_hold;
  assign id_issue    = ifid_vld && !id_stall && !ex_hold && !flush;
  // ID/EX valid flop: write only when it can change (load a new instruction,
  // or clear a valid one). Writing 0 over 0 every cycle kept D_IDEX / D_EX
  // "busy" forever, so clock gating never engaged during WFI sleep.
  assign idex_vld_we = !ex_hold && (id_issue || ex_vld);
  assign pg_stall    = mem_stall || (ifid_vld && res_stall && !load_use && !ex_hold);
endmodule : hazard_unit

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/trap_unit.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/trap_unit.sv
// Module    : trap_unit
// Content   : trap entry / exit and WFI: interrupt take, exception / mret / WFI / branch flush and target, WFI sleep flag (retention flop), core-asleep and trap-window signals
// Hierarchy : fido_top > u_core (rv32im_core) > u_trap
// Power leaf: CORE (clock net CORE)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module trap_unit (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        pd_on,
  input  wire        pd_ret,
  input  wire        pd_init,
  // CSR state
  input  wire        st_mie,
  input  wire        mie_meie,
  input  wire [31:0] mtvec,
  input  wire [31:0] mepc,
  input  wire        evq_irq,
  // EX
  input  wire        ex_vld,
  input  wire        ex_exc,
  input  wire        ex_mret,
  input  wire        ex_wfi,
  input  wire        ex_redirect,
  input  wire [31:0] ex_target,
  input  wire [31:0] ex_pc,
  input  wire        ex_mdu_started,
  input  wire        ex_adv,
  // pipeline occupancy
  input  wire        ifid_vld,
  input  wire        exmem_vld,
  input  wire        memwb_vld,
  output logic        irq_take,
  output logic        trap,          // EX instruction traps (exception or interrupt)
  output logic        trap_en,       // trap taken this cycle
  output logic        mret_en,       // mret taken this cycle
  output logic        flush,
  output logic [31:0] flush_target,
  output logic        wfi_flag,
  output logic        wfi_en,        // WFI flag written
  output logic        sleep,         // core asleep: WFI and pipeline drained
  output logic        trap_win       // trap / mret in EX (no new gating)
);
  logic wake_cond;
  logic wfi_set;
  logic wfi_clr;

  assign irq_take  = st_mie && mie_meie && evq_irq && !ex_mdu_started;
  assign trap      = ex_vld && (ex_exc || irq_take);
  assign trap_en   = ex_adv && trap;
  assign mret_en   = ex_adv && ex_mret && !trap;
  assign wake_cond = mie_meie && evq_irq;
  assign wfi_set   = ex_adv && ex_wfi && !trap && !wake_cond;
  assign wfi_clr   = wfi_flag && wake_cond;
  assign wfi_en    = wfi_set || wfi_clr;
  assign flush     = ex_adv && (trap || ex_mret || ex_wfi || ex_redirect);

  assign flush_target = trap    ? {mtvec[31:2], 2'b00} :
                        ex_mret ? mepc :
                        ex_wfi  ? (ex_pc + 32'd4) : ex_target;

  pg_dff #(.W(1), .RV(1'b0), .RET(1)) u_wfi (
    .clk     (clk),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .en      (wfi_en),
    .d       (wfi_set),
    .q       (wfi_flag)
  );

  assign sleep    = wfi_flag && !ifid_vld && !ex_vld && !exmem_vld && !memwb_vld;
  assign trap_win = ex_vld && (trap || ex_mret);
endmodule : trap_unit

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/csr_unit.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/csr_unit.sv
// Module    : csr_unit
// Content   : machine-mode CSRs (retention flops): mstatus.MIE/MPIE, mie.MEIE, mtvec, mscratch, mepc, mcause, pm_ctrl (0x7C0); read-only misa, mip.MEIP, mcycle / minstret views. CSR read mux, CSRRW/RS/RC(I) write, trap / mret updates.
// Hierarchy : fido_top > u_core (rv32im_core) > u_csr
// Power leaf: CORE (clock net CORE)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module csr_unit (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        pd_on,
  input  wire        pd_ret,
  input  wire        pd_init,
  // CSR instruction in EX
  input  wire        ex_csr,
  input  wire [11:0] ex_csr_addr,
  input  wire  [2:0] ex_f3,
  input  wire [31:0] ex_csr_src,
  input  wire        ex_csr_wnz,     // rs1 / uimm field != 0
  input  wire        ex_adv,
  // traps
  input  wire        trap,
  input  wire        trap_en,
  input  wire        mret_en,
  input  wire        irq_take,
  input  wire  [3:0] ex_exc_code,
  input  wire [31:0] ex_pc,
  // read-only sources
  input  wire        evq_irq,
  input  wire [31:0] mcycle,
  input  wire [31:0] minstret,
  output logic [31:0] csr_rdata,
  output logic        st_mie,
  output logic        mie_meie,
  output logic [31:0] mtvec,
  output logic [31:0] mepc,
  output logic        we              // any CSR written (clock-gating busy)
);
  wire        st_mpie;
  wire [31:0] mcause;
  wire [31:0] mscratch;
  wire [31:0] pm_ctrl;

  logic        csr_wr;
  logic [31:0] csr_new;
  logic        wr_mstatus;
  logic        wr_mie;
  logic        wr_mtvec;
  logic        wr_mscratch;
  logic        wr_mepc;
  logic        wr_mcause;
  logic        wr_pmctrl;
  logic [31:0] cause_val;
  logic        st_en;
  logic        n_mie;
  logic        n_mpie;
  logic        epc_en;
  logic [31:0] n_mepc;
  logic        cau_en;
  logic [31:0] n_mcause;

  //------------------------------------------------ read mux
  always_comb begin
    case (ex_csr_addr)
      12'h300: csr_rdata = {19'd0, 2'b11, 3'd0, st_mpie, 3'd0, st_mie, 3'd0};   // mstatus
      12'h301: csr_rdata = 32'h4000_1100;                                       // misa RV32IM
      12'h304: csr_rdata = {20'd0, mie_meie, 11'd0};                            // mie
      12'h305: csr_rdata = mtvec;
      12'h340: csr_rdata = mscratch;
      12'h341: csr_rdata = mepc;
      12'h342: csr_rdata = mcause;
      12'h344: csr_rdata = {20'd0, evq_irq, 11'd0};                             // mip
      12'h7C0: csr_rdata = pm_ctrl;
      12'hB00: csr_rdata = mcycle;
      12'hB02: csr_rdata = minstret;
      12'hC00: csr_rdata = mcycle;
      12'hC02: csr_rdata = minstret;
      default: csr_rdata = 32'd0;
    endcase
  end

  //------------------------------------------------ write
  assign csr_wr      = ex_adv && ex_csr && !trap && ((ex_f3[1:0] == 2'b01) || ex_csr_wnz);
  assign csr_new     = (ex_f3[1:0] == 2'b01) ? ex_csr_src :
                       (ex_f3[1:0] == 2'b10) ? (csr_rdata | ex_csr_src) :
                                               (csr_rdata & ~ex_csr_src);
  assign wr_mstatus  = csr_wr && (ex_csr_addr == 12'h300);
  assign wr_mie      = csr_wr && (ex_csr_addr == 12'h304);
  assign wr_mtvec    = csr_wr && (ex_csr_addr == 12'h305);
  assign wr_mscratch = csr_wr && (ex_csr_addr == 12'h340);
  assign wr_mepc     = csr_wr && (ex_csr_addr == 12'h341);
  assign wr_mcause   = csr_wr && (ex_csr_addr == 12'h342);
  assign wr_pmctrl   = csr_wr && (ex_csr_addr == 12'h7C0);

  assign cause_val = irq_take ? 32'h8000_000B : {28'd0, ex_exc_code};
  assign st_en     = wr_mstatus || trap_en || mret_en;
  assign n_mie     = trap_en ? 1'b0 : (mret_en ? st_mpie : csr_new[3]);
  assign n_mpie    = trap_en ? st_mie : (mret_en ? 1'b1 : csr_new[7]);
  assign epc_en    = wr_mepc || trap_en;
  assign n_mepc    = trap_en ? ex_pc : {csr_new[31:2], 2'b00};
  assign cau_en    = wr_mcause || trap_en;
  assign n_mcause  = trap_en ? cause_val : csr_new;

  //------------------------------------------------ registers (retention)
  pg_dff #(.W(2), .RV(2'b00), .RET(1)) u_mstatus (
    .clk(clk), .rst_n(rst_n), .pd_on(pd_on), .pd_ret(pd_ret), .pd_init(pd_init),
    .en(st_en), .d({n_mie, n_mpie}), .q({st_mie, st_mpie}));

  pg_dff #(.W(1), .RV(1'b0), .RET(1)) u_mie (
    .clk(clk), .rst_n(rst_n), .pd_on(pd_on), .pd_ret(pd_ret), .pd_init(pd_init),
    .en(wr_mie), .d(csr_new[11]), .q(mie_meie));

  pg_dff #(.W(32), .RV(32'd0), .RET(1)) u_mtvec (
    .clk(clk), .rst_n(rst_n), .pd_on(pd_on), .pd_ret(pd_ret), .pd_init(pd_init),
    .en(wr_mtvec), .d({csr_new[31:2], 2'b00}), .q(mtvec));

  pg_dff #(.W(32), .RV(32'd0), .RET(1)) u_mepc (
    .clk(clk), .rst_n(rst_n), .pd_on(pd_on), .pd_ret(pd_ret), .pd_init(pd_init),
    .en(epc_en), .d(n_mepc), .q(mepc));

  pg_dff #(.W(32), .RV(32'd0), .RET(1)) u_mcause (
    .clk(clk), .rst_n(rst_n), .pd_on(pd_on), .pd_ret(pd_ret), .pd_init(pd_init),
    .en(cau_en), .d(n_mcause), .q(mcause));

  pg_dff #(.W(32), .RV(32'd0), .RET(1)) u_mscratch (
    .clk(clk), .rst_n(rst_n), .pd_on(pd_on), .pd_ret(pd_ret), .pd_init(pd_init),
    .en(wr_mscratch), .d(csr_new), .q(mscratch));

  pg_dff #(.W(32), .RV(32'd0), .RET(1)) u_pmctrl (
    .clk(clk), .rst_n(rst_n), .pd_on(pd_on), .pd_ret(pd_ret), .pd_init(pd_init),
    .en(wr_pmctrl), .d(csr_new), .q(pm_ctrl));

  assign we = st_en || wr_mie || wr_mtvec || epc_en || cau_en || wr_mscratch || wr_pmctrl;
endmodule : csr_unit

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/mem_stage.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/mem_stage.sv
// Module    : mem_stage
// Content   : MEM stage: EX/MEM register (clock net EXMEM), LSU - address decode, bank select (range or interleave), store strobes, load align / extend, MMIO (event queue, TOHOST), stall while a bank wakes, per-bank demand for the PMU. Memory map: 0x0001_0000-0x0001_0FFF data banks; 0x0002_0000 EVQ STATUS, 0x0002_0004 EVQ POP, 0x0002_0008 EVQ CFG; 0x0003_0000 TOHOST
// Hierarchy : fido_top > u_core (rv32im_core) > u_mem
// Power leaf: CORE (clock net EXMEM)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module mem_stage #(
  parameter int BANK_MAP = 0     // 0 = address range (addr[11:10]), 1 = word interleave (addr[3:2])
) (
  input  wire         clk,
  input  wire         rst_n,
  input  wire         pd_on,
  input  wire         pd_ret,
  input  wire         pd_init,
  input  wire         ex_adv,
  input  wire         trap,
  // from EX
  input  wire         ex_vld,
  input  wire  [31:0] ex_pc,
  input  wire  [31:0] ex_insn,
  input  wire   [4:0] ex_rd,
  input  wire         ex_wen,
  input  wire  [31:0] ex_res,
  input  wire         ex_load,
  input  wire         ex_store,
  input  wire   [2:0] ex_f3,
  input  wire  [31:0] ex_addr,
  input  wire  [31:0] ex_sdata,
  // banks / event queue
  input  wire   [3:0] bank_rdy,      // per bank: domain ready
  input  wire [127:0] dm_rdata,
  input  wire   [3:0] evq_count,
  input  wire   [9:0] evq_head,
  input  wire         evq_ovf,
  // EX/MEM register contents
  output logic        exmem_vld,
  output logic [31:0] exmem_pc,
  output logic [31:0] exmem_insn,
  output logic  [4:0] exmem_rd,
  output logic        exmem_wen,
  output logic        exmem_load,
  output logic [31:0] exmem_res,
  output logic        exmem_store,
  output logic [31:0] exmem_addr,
  output logic [31:0] exmem_sdata,
  // LSU results
  output logic        mem_stall,
  output logic        mem_go,        // MEM instruction completes this cycle
  output logic [31:0] wb_val,        // load data or EX result
  output logic [31:0] st_data,
  output logic  [3:0] st_strb,
  output logic  [7:0] dm_idx,
  output logic  [3:0] dm_we,
  output logic        evq_pop,
  output logic        evq_cfg_we,
  output logic        tohost_we,
  output logic  [3:0] bank_dem,      // per bank demand (EX address or MEM access)
  output logic        we             // EX/MEM register written (clock-gating busy)
);
  //------------------------------------------------ EX/MEM register
  logic       exmem_take;
  logic       exmem_vld_en;
  logic [2:0] exmem_f3;

  assign exmem_take   = ex_adv && !trap;
  assign exmem_vld_en = !mem_stall && (exmem_vld || ex_adv);

  pipe_reg #(.W(171)) u_exmem (
    .clk     (clk),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .vld_en  (exmem_vld_en),
    .vld_d   (exmem_take),
    .data_en (exmem_take),
    .d       ({ex_pc, ex_insn, ex_rd, ex_wen, ex_res, ex_load, ex_store, ex_f3, ex_addr, ex_sdata}),
    .vld_q   (exmem_vld),
    .q       ({exmem_pc, exmem_insn, exmem_rd, exmem_wen, exmem_res, exmem_load, exmem_store,
               exmem_f3, exmem_addr, exmem_sdata})
  );

  //------------------------------------------------ address decode
  logic        dm_hit;
  logic        evq_hit;
  logic        th_hit;
  logic  [1:0] bank;
  logic        mem_access;
  logic        bank_ok;
  logic [31:0] bank_word;
  logic [31:0] evq_word;
  logic [31:0] raw_word;
  logic [31:0] sh_word;
  logic [31:0] ld_val;
  logic        ex_dm_hit;
  logic  [1:0] ex_bank;
  logic        ex_dm_acc;

  assign dm_hit     = (exmem_addr[31:12] == 20'h00010);
  assign evq_hit    = (exmem_addr[31:4]  == 28'h0002000);
  assign th_hit     = (exmem_addr == 32'h0003_0000);
  assign bank       = (BANK_MAP == 0) ? exmem_addr[11:10] : exmem_addr[3:2];
  assign dm_idx     = (BANK_MAP == 0) ? exmem_addr[9:2]   : exmem_addr[11:4];
  assign mem_access = exmem_vld && (exmem_load || exmem_store) && dm_hit;
  assign bank_ok    = (bank == 2'd0) ? bank_rdy[0] : (bank == 2'd1) ? bank_rdy[1] :
                      (bank == 2'd2) ? bank_rdy[2] : bank_rdy[3];
  assign mem_stall  = mem_access && !bank_ok;
  assign mem_go     = exmem_vld && !mem_stall;

  //------------------------------------------------ store
  always_comb begin
    case (exmem_f3[1:0])
      2'b00: begin
        st_strb = 4'b0001 << exmem_addr[1:0];
        st_data = {4{exmem_sdata[7:0]}};
      end
      2'b01: begin
        st_strb = exmem_addr[1] ? 4'b1100 : 4'b0011;
        st_data = {2{exmem_sdata[15:0]}};
      end
      default: begin
        st_strb = 4'b1111;
        st_data = exmem_sdata;
      end
    endcase
  end

  //------------------------------------------------ load
  assign bank_word = dm_rdata[{bank, 5'b00000} +: 32];   // bank * 32
  assign evq_word  = (exmem_addr[3:2] == 2'd0) ? {evq_ovf, 27'd0, evq_count} :
                     (exmem_addr[3:2] == 2'd1) ? {(evq_count != 4'd0), 21'd0, evq_head} : 32'd0;
  assign raw_word  = dm_hit ? bank_word : (evq_hit ? evq_word : 32'd0);
  assign sh_word   = raw_word >> {exmem_addr[1:0], 3'b000};

  always_comb begin
    case (exmem_f3)
      3'b000:  ld_val = {{24{sh_word[7]}},  sh_word[7:0]};
      3'b001:  ld_val = {{16{sh_word[15]}}, sh_word[15:0]};
      3'b100:  ld_val = {24'd0, sh_word[7:0]};
      3'b101:  ld_val = {16'd0, sh_word[15:0]};
      default: ld_val = raw_word;
    endcase
  end

  assign wb_val = exmem_load ? ld_val : exmem_res;

  //------------------------------------------------ write strobes / MMIO
  assign dm_we      = {(mem_go && exmem_store && dm_hit && (bank == 2'd3)),
                       (mem_go && exmem_store && dm_hit && (bank == 2'd2)),
                       (mem_go && exmem_store && dm_hit && (bank == 2'd1)),
                       (mem_go && exmem_store && dm_hit && (bank == 2'd0))};
  assign evq_pop    = mem_go && exmem_load  && evq_hit && (exmem_addr[3:2] == 2'd1);
  assign evq_cfg_we = mem_go && exmem_store && evq_hit && (exmem_addr[3:2] == 2'd2);
  assign tohost_we  = mem_go && exmem_store && th_hit;

  //------------------------------------------------ bank demand (PMU)
  assign ex_dm_hit   = (ex_addr[31:12] == 20'h00010);
  assign ex_bank     = (BANK_MAP == 0) ? ex_addr[11:10] : ex_addr[3:2];
  assign ex_dm_acc   = ex_vld && (ex_load || ex_store) && ex_dm_hit;
  assign bank_dem    = {((ex_dm_acc && (ex_bank == 2'd3)) || (mem_access && (bank == 2'd3))),
                        ((ex_dm_acc && (ex_bank == 2'd2)) || (mem_access && (bank == 2'd2))),
                        ((ex_dm_acc && (ex_bank == 2'd1)) || (mem_access && (bank == 2'd1))),
                        ((ex_dm_acc && (ex_bank == 2'd0)) || (mem_access && (bank == 2'd0)))};

  assign we = exmem_vld_en || exmem_take;
endmodule : mem_stage

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/wb_stage.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/wb_stage.sv
// Module    : wb_stage
// Content   : WB stage: MEM/WB register (clock net MEMWB), register write-back
//             enable and the retirement trace (RVFI-style) of every
//             instruction that leaves the pipeline.
// Hierarchy : fido_top > u_core (rv32im_core) > u_wb
// Power leaf: CORE (clock net MEMWB)
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module wb_stage (
  input  wire        clk,
  input  wire        rst_n,
  input  wire        pd_on,
  input  wire        pd_ret,
  input  wire        pd_init,
  // from MEM
  input  wire        mem_stall,
  input  wire        mem_go,
  input  wire        exmem_vld,
  input  wire [31:0] exmem_pc,
  input  wire [31:0] exmem_insn,
  input  wire  [4:0] exmem_rd,
  input  wire        exmem_wen,
  input  wire [31:0] wb_val,
  input  wire        exmem_store,
  input  wire [31:0] exmem_addr,
  input  wire [31:0] st_data,
  input  wire  [3:0] st_strb,
  // MEM/WB register contents
  output logic        memwb_vld,
  output logic  [4:0] memwb_rd,
  output logic        memwb_wen,
  output logic [31:0] memwb_wdata,
  // write-back
  output logic        wb_we,
  // retirement trace
  output logic        rv_valid,
  output logic [31:0] rv_pc,
  output logic [31:0] rv_insn,
  output logic  [4:0] rv_rd,
  output logic [31:0] rv_wdata,
  output logic        rv_mem_we,
  output logic [31:0] rv_mem_addr,
  output logic [31:0] rv_mem_wdata,
  output logic  [3:0] rv_mem_strb,
  output logic        we             // MEM/WB register written (clock-gating busy)
);
  wire [31:0] memwb_pc;
  wire [31:0] memwb_insn;
  wire        memwb_mwe;
  wire [31:0] memwb_maddr;
  wire [31:0] memwb_mwdata;
  wire  [3:0] memwb_mstrb;
  logic       memwb_vld_en;

  assign memwb_vld_en = !mem_stall && (memwb_vld || exmem_vld);

  // 32+32+5+1+32+1+32+32+4 = 171 bits
  pipe_reg #(.W(171)) u_memwb (
    .clk     (clk),
    .rst_n   (rst_n),
    .pd_on   (pd_on),
    .pd_ret  (pd_ret),
    .pd_init (pd_init),
    .vld_en  (memwb_vld_en),
    .vld_d   (exmem_vld),
    .data_en (mem_go),
    .d       ({exmem_pc, exmem_insn, exmem_rd, exmem_wen, wb_val, exmem_store, exmem_addr,
               (exmem_store ? st_data : 32'd0), (exmem_store ? st_strb : 4'd0)}),
    .vld_q   (memwb_vld),
    .q       ({memwb_pc, memwb_insn, memwb_rd, memwb_wen, memwb_wdata, memwb_mwe, memwb_maddr,
               memwb_mwdata, memwb_mstrb})
  );

  assign wb_we        = memwb_vld && memwb_wen && !mem_stall;

  assign rv_valid     = memwb_vld && !mem_stall;
  assign rv_pc        = memwb_pc;
  assign rv_insn      = memwb_insn;
  assign rv_rd        = memwb_wen ? memwb_rd : 5'd0;
  assign rv_wdata     = memwb_wen ? memwb_wdata : 32'd0;
  assign rv_mem_we    = memwb_mwe;
  assign rv_mem_addr  = memwb_mwe ? memwb_maddr : 32'd0;
  assign rv_mem_wdata = memwb_mwdata;
  assign rv_mem_strb  = memwb_mstrb;

  assign we = memwb_vld_en || mem_go;
endmodule : wb_stage

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> rtl/core/rv32im_core.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL
// File      : rtl/core/rv32im_core.sv
// Module    : rv32im_core
// Content   : 5-stage RV32IM pipeline with forwarding, load-use interlock,
//             CSRs, traps, WFI and per-clock-net gating hooks.
//               u_if   if_stage     PC, IF/ID                      CORE leaf
//               u_id   id_stage     decode, immediates             CORE leaf
//               u_rf   regfile      bank LO (CORE) + bank HI (RF_HI leaf)
//               u_hz   hazard_unit  load-use, readiness, issue     CORE leaf
//               u_trap trap_unit    traps, mret, WFI flag, flush   CORE leaf
//               u_csr  csr_unit     machine-mode CSRs              CORE leaf
//               u_ex   ex_stage     ID/EX + ALU/MUL/DIV            EX / ALU_HI / MUL / DIV leaves
//               u_mem  mem_stage    EX/MEM + LSU                   CORE leaf
//               u_wb   wb_stage     MEM/WB + retirement            CORE leaf
//             Every signal leaving the CORE leaf passes isolation cells
//             (clamp 0, except wfi_sleep which clamps to 1 = "asleep").
//             Clock nets / power leaves are indexed as in fido_pkg (CN_*).
// Hierarchy : fido_top > u_core
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module rv32im_core
  import fido_pkg::*;
#(
  parameter int BANK_MAP = 0     // 0 = address range, 1 = word interleave
) (
  input  wire  [17:0]  gclk_cn,      // gated clock per clock net
  input  wire          rst_n,
  input  wire  [17:0]  on_cn,        // power leaf of the net is powered
  input  wire  [17:0]  ret_cn,       // retention save request
  input  wire  [17:0]  init_cn,      // power-up init
  input  wire  [17:0]  iso_cn,       // isolation enable
  input  wire  [17:0]  rdy_cn,       // domain ready (not power-gated)
  // instruction memory
  input  wire  [31:0]  imem_rdata,
  output logic [31:0]  imem_addr,
  // data-memory banks
  output logic  [7:0]  dm_idx,
  output logic  [3:0]  dm_we,
  output logic  [3:0]  dm_strb,
  output logic [31:0]  dm_wdata,
  input  wire [127:0]  dm_rdata,
  // event queue
  output logic         evq_pop,
  output logic         evq_cfg_we,
  output logic  [3:0]  evq_cfg_wdata,
  input  wire   [3:0]  evq_count,
  input  wire   [9:0]  evq_head,
  input  wire          evq_ovf,
  input  wire          evq_irq,
  // always-on counters
  input  wire  [31:0]  mcycle,
  input  wire  [31:0]  minstret,
  // retirement trace / status
  output logic         rv_valid,
  output logic [31:0]  rv_pc,
  output logic [31:0]  rv_insn,
  output logic  [4:0]  rv_rd,
  output logic [31:0]  rv_wdata,
  output logic         rv_mem_we,
  output logic [31:0]  rv_mem_addr,
  output logic [31:0]  rv_mem_wdata,
  output logic  [3:0]  rv_mem_strb,
  output logic         tohost_we,
  output logic [31:0]  tohost_data,
  // PMU sensing (isolated at their leaf boundary)
  output logic         we_add,
  output logic         we_logic,
  output logic         we_shift,
  output logic         we_cmp,
  output logic         we_mul,
  output logic         we_div,
  output logic         we_idex,
  output logic         we_core,
  output logic         we_exmem,
  output logic         we_memwb,
  output logic         rfh_we,
  output logic  [3:0]  bank_dem,
  output logic         rfh_dem,
  output logic         id_vld_o,
  output logic  [2:0]  id_unit_o,
  output logic         ex_vld_o,
  output logic  [2:0]  ex_unit_o,
  output logic         mul_busy,
  output logic         div_busy,
  output logic         exmem_vld_o,
  output logic         memwb_vld_o,
  output logic         wfi_sleep,
  output logic         trap_win,
  output logic         pg_stall
);
  //================================================================ CORE-leaf signals
  // IF
  wire [31:0] pc;
  wire        ifid_vld;
  wire [31:0] ifid_pc;
  wire [31:0] ifid_insn;
  wire        if_we;
  // ID
  wire ctl_t  ctl;
  wire [31:0] imm;
  wire  [4:0] rs1;
  wire  [4:0] rs2;
  wire  [4:0] rd;
  wire  [2:0] unit;
  wire        uses_hi;
  // RF
  wire [31:0] r1;
  wire [31:0] r2;
  wire        rflo_we;
  // hazards
  wire        ex_adv_c;
  wire        id_issue;
  wire        idex_vld_we_c;
  wire        pg_stall_c;
  // traps
  wire        irq_take;
  wire        trap_c;
  wire        trap_en;
  wire        mret_en;
  wire        flush;
  wire [31:0] flush_target;
  wire        wfi_flag;
  wire        wfi_en;
  wire        sleep_c;
  wire        trap_win_c;
  // CSR
  wire [31:0] csr_rdata_c;
  wire        st_mie;
  wire        mie_meie;
  wire [31:0] mtvec;
  wire [31:0] mepc;
  wire        csr_we;
  // MEM
  wire        exmem_vld;
  wire [31:0] exmem_pc;
  wire [31:0] exmem_insn;
  wire  [4:0] exmem_rd;
  wire        exmem_wen;
  wire        exmem_load;
  wire [31:0] exmem_res;
  wire        exmem_store;
  wire [31:0] exmem_addr;
  wire [31:0] exmem_sdata;
  wire        mem_stall;
  wire        mem_go;
  wire [31:0] wb_val;
  wire [31:0] st_data;
  wire  [3:0] st_strb;
  wire  [7:0] dm_idx_c;
  wire  [3:0] dm_we_c;
  wire        evq_pop_c;
  wire        evq_cfg_we_c;
  wire        tohost_we_c;
  wire  [3:0] bank_dem_c;
  wire        mem_we;
  // WB
  wire        memwb_vld;
  wire  [4:0] memwb_rd;
  wire        memwb_wen;
  wire [31:0] memwb_wdata;
  wire        wb_we;
  wire        rv_valid_c;
  wire [31:0] rv_pc_c;
  wire [31:0] rv_insn_c;
  wire  [4:0] rv_rd_c;
  wire [31:0] rv_wdata_c;
  wire        rv_mem_we_c;
  wire [31:0] rv_mem_addr_c;
  wire [31:0] rv_mem_wdata_c;
  wire  [3:0] rv_mem_strb_c;
  wire        wb_we_busy;

  //================================================================ CORE -> EX (isolated)
  wire        x_id_load;
  wire        x_idex_vld_we;
  wire [31:0] x_id_pc;
  wire [31:0] x_id_insn;
  wire [31:0] x_id_imm;
  wire [31:0] x_id_r1;
  wire [31:0] x_id_r2;
  wire  [4:0] x_id_rd;
  wire  [4:0] x_id_rs1;
  wire  [4:0] x_id_rs2;
  wire ctl_t  x_id_ctl;
  wire        x_take_trap;
  wire        x_ex_adv;
  wire        x_fw_exmem_vld;
  wire        x_fw_exmem_wen;
  wire  [4:0] x_fw_exmem_rd;
  wire [31:0] x_fw_exmem_res;
  wire        x_fw_memwb_vld;
  wire        x_fw_memwb_wen;
  wire  [4:0] x_fw_memwb_rd;
  wire [31:0] x_fw_memwb_wdata;
  wire [31:0] x_csr_rdata;

  //================================================================ EX -> CORE (isolated in ex_stage)
  wire        ex_vld;
  wire [31:0] ex_pc;
  wire [31:0] ex_insn;
  wire  [4:0] ex_rd;
  wire        ex_wen;
  wire [31:0] ex_res;
  wire        ex_load;
  wire        ex_store;
  wire  [2:0] ex_f3;
  wire [31:0] ex_addr;
  wire [31:0] ex_sdata;
  wire        ex_redirect;
  wire [31:0] ex_target;
  wire        ex_exc;
  wire  [3:0] ex_exc_code;
  wire        ex_mret;
  wire        ex_wfi;
  wire        ex_csr;
  wire [11:0] ex_csr_addr;
  wire [31:0] ex_csr_src;
  wire        ex_csr_wnz;
  wire        ex_stall;
  wire        ex_mdu_started;
  wire  [2:0] ex_unit;

  //================================================================ IF
  if_stage u_if (
    .clk          (gclk_cn[CN_CORE]),
    .rst_n        (rst_n),
    .pd_on        (on_cn[CN_CORE]),
    .pd_ret       (ret_cn[CN_CORE]),
    .pd_init      (init_cn[CN_CORE]),
    .flush        (flush),
    .flush_target (flush_target),
    .id_issue     (id_issue),
    .wfi_flag     (wfi_flag),
    .imem_rdata   (imem_rdata),
    .pc           (pc),
    .ifid_vld     (ifid_vld),
    .ifid_pc      (ifid_pc),
    .ifid_insn    (ifid_insn),
    .we           (if_we)
  );

  //================================================================ ID
  id_stage u_id (
    .ifid_insn (ifid_insn),
    .ctl       (ctl),
    .imm       (imm),
    .rs1       (rs1),
    .rs2       (rs2),
    .rd        (rd),
    .unit      (unit),
    .uses_hi   (uses_hi)
  );

  //================================================================ register file
  regfile u_rf (
    .clk_lo   (gclk_cn[CN_CORE]),
    .clk_hi   (gclk_cn[CN_RFHI]),
    .rst_n    (rst_n),
    .pdc_on   (on_cn[CN_CORE]),
    .pdc_ret  (ret_cn[CN_CORE]),
    .pdc_iso  (iso_cn[CN_CORE]),
    .pdh_on   (on_cn[CN_RFHI]),
    .pdh_ret  (ret_cn[CN_RFHI]),
    .pdh_iso  (iso_cn[CN_RFHI]),
    .rs1      (rs1),
    .rs2      (rs2),
    .wb_we    (wb_we),
    .wb_rd    (memwb_rd),
    .wb_wdata (memwb_wdata),
    .r1       (r1),
    .r2       (r2),
    .rflo_we  (rflo_we),
    .rfh_we   (rfh_we)
  );

  //================================================================ hazards
  hazard_unit u_hz (
    .ifid_vld    (ifid_vld),
    .urs1        (ctl.urs1),
    .urs2        (ctl.urs2),
    .rs1         (rs1),
    .rs2         (rs2),
    .unit        (unit),
    .uses_hi     (uses_hi),
    .ex_vld      (ex_vld),
    .ex_load     (ex_load),
    .ex_rd       (ex_rd),
    .ex_stall    (ex_stall),
    .mem_stall   (mem_stall),
    .flush       (flush),
    .cn_ready    (rdy_cn),
    .ex_adv      (ex_adv_c),
    .id_issue    (id_issue),
    .idex_vld_we (idex_vld_we_c),
    .pg_stall    (pg_stall_c)
  );

  //================================================================ traps / WFI
  trap_unit u_trap (
    .clk            (gclk_cn[CN_CORE]),
    .rst_n          (rst_n),
    .pd_on          (on_cn[CN_CORE]),
    .pd_ret         (ret_cn[CN_CORE]),
    .pd_init        (init_cn[CN_CORE]),
    .st_mie         (st_mie),
    .mie_meie       (mie_meie),
    .mtvec          (mtvec),
    .mepc           (mepc),
    .evq_irq        (evq_irq),
    .ex_vld         (ex_vld),
    .ex_exc         (ex_exc),
    .ex_mret        (ex_mret),
    .ex_wfi         (ex_wfi),
    .ex_redirect    (ex_redirect),
    .ex_target      (ex_target),
    .ex_pc          (ex_pc),
    .ex_mdu_started (ex_mdu_started),
    .ex_adv         (ex_adv_c),
    .ifid_vld       (ifid_vld),
    .exmem_vld      (exmem_vld),
    .memwb_vld      (memwb_vld),
    .irq_take       (irq_take),
    .trap           (trap_c),
    .trap_en        (trap_en),
    .mret_en        (mret_en),
    .flush          (flush),
    .flush_target   (flush_target),
    .wfi_flag       (wfi_flag),
    .wfi_en         (wfi_en),
    .sleep          (sleep_c),
    .trap_win       (trap_win_c)
  );

  //================================================================ CSRs
  csr_unit u_csr (
    .clk         (gclk_cn[CN_CORE]),
    .rst_n       (rst_n),
    .pd_on       (on_cn[CN_CORE]),
    .pd_ret      (ret_cn[CN_CORE]),
    .pd_init     (init_cn[CN_CORE]),
    .ex_csr      (ex_csr),
    .ex_csr_addr (ex_csr_addr),
    .ex_f3       (ex_f3),
    .ex_csr_src  (ex_csr_src),
    .ex_csr_wnz  (ex_csr_wnz),
    .ex_adv      (ex_adv_c),
    .trap        (trap_c),
    .trap_en     (trap_en),
    .mret_en     (mret_en),
    .irq_take    (irq_take),
    .ex_exc_code (ex_exc_code),
    .ex_pc       (ex_pc),
    .evq_irq     (evq_irq),
    .mcycle      (mcycle),
    .minstret    (minstret),
    .csr_rdata   (csr_rdata_c),
    .st_mie      (st_mie),
    .mie_meie    (mie_meie),
    .mtvec       (mtvec),
    .mepc        (mepc),
    .we          (csr_we)
  );

  //================================================================ CORE -> EX isolation
  // one isolation cell per signal leaving the CORE leaf (clamp 0)
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_id_load (.iso(iso_cn[CN_CORE]), .d(id_issue), .q(x_id_load));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_idex_vld_we (.iso(iso_cn[CN_CORE]), .d(idex_vld_we_c), .q(x_idex_vld_we));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_id_pc (.iso(iso_cn[CN_CORE]), .d(ifid_pc), .q(x_id_pc));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_id_insn (.iso(iso_cn[CN_CORE]), .d(ifid_insn), .q(x_id_insn));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_id_imm (.iso(iso_cn[CN_CORE]), .d(imm), .q(x_id_imm));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_id_r1 (.iso(iso_cn[CN_CORE]), .d(r1), .q(x_id_r1));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_id_r2 (.iso(iso_cn[CN_CORE]), .d(r2), .q(x_id_r2));
  iso_clamp #(.W(5), .CLAMP(5'd0)) u_iso_id_rd (.iso(iso_cn[CN_CORE]), .d(rd), .q(x_id_rd));
  iso_clamp #(.W(5), .CLAMP(5'd0)) u_iso_id_rs1 (.iso(iso_cn[CN_CORE]), .d(rs1), .q(x_id_rs1));
  iso_clamp #(.W(5), .CLAMP(5'd0)) u_iso_id_rs2 (.iso(iso_cn[CN_CORE]), .d(rs2), .q(x_id_rs2));
  iso_clamp #(.W(24), .CLAMP(24'd0)) u_iso_id_ctl (.iso(iso_cn[CN_CORE]), .d(ctl), .q(x_id_ctl));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_take_trap (.iso(iso_cn[CN_CORE]), .d(trap_c), .q(x_take_trap));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_ex_adv (.iso(iso_cn[CN_CORE]), .d(ex_adv_c), .q(x_ex_adv));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_fw_exmem_vld (.iso(iso_cn[CN_CORE]), .d(exmem_vld), .q(x_fw_exmem_vld));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_fw_exmem_wen (.iso(iso_cn[CN_CORE]), .d((exmem_wen && !exmem_load)), .q(x_fw_exmem_wen));
  iso_clamp #(.W(5), .CLAMP(5'd0)) u_iso_fw_exmem_rd (.iso(iso_cn[CN_CORE]), .d(exmem_rd), .q(x_fw_exmem_rd));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_fw_exmem_res (.iso(iso_cn[CN_CORE]), .d(exmem_res), .q(x_fw_exmem_res));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_fw_memwb_vld (.iso(iso_cn[CN_CORE]), .d(memwb_vld), .q(x_fw_memwb_vld));
  iso_clamp #(.W(1), .CLAMP(1'd0)) u_iso_fw_memwb_wen (.iso(iso_cn[CN_CORE]), .d(memwb_wen), .q(x_fw_memwb_wen));
  iso_clamp #(.W(5), .CLAMP(5'd0)) u_iso_fw_memwb_rd (.iso(iso_cn[CN_CORE]), .d(memwb_rd), .q(x_fw_memwb_rd));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_fw_memwb_wdata (.iso(iso_cn[CN_CORE]), .d(memwb_wdata), .q(x_fw_memwb_wdata));
  iso_clamp #(.W(32), .CLAMP(32'd0)) u_iso_csr_rdata (.iso(iso_cn[CN_CORE]), .d(csr_rdata_c), .q(x_csr_rdata));

  //================================================================ EX
  ex_stage u_ex (
    .clk_add_lo     (gclk_cn[CN_ADD_LO]),
    .clk_add_hi     (gclk_cn[CN_ADD_HI]),
    .clk_logic_lo   (gclk_cn[CN_LOGIC_LO]),
    .clk_logic_hi   (gclk_cn[CN_LOGIC_HI]),
