  iso_clamp #(.W(1), .CLAMP(1'b1)) u_iso_sleep (.iso(iso_cn[CN_CORE]), .d(sleep_c), .q(wfi_sleep));

  // EX-leaf signals for the PMU (already isolated inside ex_stage)
  assign ex_vld_o  = ex_vld;
  assign ex_unit_o = ex_unit;
