// >>> rtl/fido_top.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog RTL, shared by SYRAX (P1) and CARAXES (P2)
// File      : rtl/fido_top.sv
